window.KB=window.KB||{};window.KB['图论']=[{"id": "graph-37", "title": "图论 01 · 最小生成树", "cat": "图论", "blocks": [{"k": "h4", "x": "定义"}, {"k": "p", "x": "设 G = (V, E, w) 为一个连通无向带权图，其中："}, {"k": "li", "x": "V 是顶点集，"}, {"k": "li", "x": "E 是边集，"}, {"k": "li", "x": "w: E -> R 是边权函数（赋予每条边一个实数权重）。"}, {"k": "p", "x": "生成树（Spanning Tree）是 G 的一个子图 T = (V, E_(T)) ，满足："}, {"k": "li", "x": "T 包含 G 的所有顶点（即顶点集与 G 相同）；"}, {"k": "li", "x": "T 是一棵树（连通、无环，且恰好有 |V| - 1 条边）。"}, {"k": "p", "x": "若生成树 T 的所有边权之和 w(T) = sum (e 属于 E(T)) w(e) 在 G 的所有生成树中最小，则称 T 为 G 的 最小生成树。"}, {"k": "h4", "x": "*补充说明*"}, {"k": "li", "x": "存在性：当且仅当图 G 是连通图时，最小生成树存在。对于非连通图，可通过最小生成森林（Minimum Spanning Forest）覆盖各连通分量。"}, {"k": "li", "x": "唯一性： 最小生成树不一定唯一。若图中存在多条权值相同的边，可能存在不同的最小生成树，但它们的边权总和必定相等。"}, {"k": "h4", "x": "Kruskal 算法"}, {"k": "p", "x": "Kruskal 算法是一种常见并且好写的最小生成树算法，由 Kruskal 发明。该算法的基本思想是从小到大加入边，是个贪心算法。"}, {"k": "h4", "x": "前置知识"}, {"k": "p", "x": "Kruskal 算法基于并查集来实现。"}, {"k": "h4", "x": "实现"}, {"k": "p", "x": "图示："}, {"k": "p", "x": "伪代码："}, {"k": "p", "x": "1 Input. The edges of the graph e , where each element in e is (u, v, w) denoting that there is an edge between u and v weighted w . 2 Output. The edges of the MST of the input graph. 3 Method. 4 result <- 空集5 sort e into nondecreasing order by weight w 6 for each (u, v, w) in the sorted e 7 if u and v are not connected in the union-find set 8 connect u and v in the union-find set 9 result <- result bigcup (u, v, w) 10 return result"}, {"k": "p", "x": "算法虽简单，但需要相应的数据结构来支持……具体来说，维护一个森林，查询两个结点是否在同一棵树中，连接两棵树。"}, {"k": "p", "x": "抽象一点地说，维护一堆 集合，查询两个元素是否属于同一集合，合并两个集合。"}, {"k": "p", "x": "其中，查询两点是否连通和连接两点可以使用并查集维护。"}, {"k": "p", "x": "如果使用 O(mlog m) 的排序算法，并且使用 O(malpha(m, n)) 或 O(mlog n) 的并查集，就可以得到时间复杂度为 O(mlog m) 的 Kruskal 算法。"}, {"k": "h4", "x": "证明"}, {"k": "p", "x": "思路很简单，为了造出一棵最小生成树，我们从最小边权的边开始，按边权从小到大依次加入，如果某次加边产生了环，就扔掉这条边，直到加入了 n-1 条边，即形成了一棵树。"}, {"k": "p", "x": "证明：使用归纳法，证明任何时候 K 算法选择的边集都被某棵 MST 所包含。"}, {"k": "p", "x": "基础：对于算法刚开始时，显然成立（最小生成树存在）。"}, {"k": "p", "x": "归纳：假设某时刻成立，当前边集为 F ，令 T 为这棵 MST，考虑下一条加入的边 e 。"}, {"k": "p", "x": "如果 e 属于 T ，那么成立。"}, {"k": "p", "x": "否则， T+e 一定存在一个环，考虑这个环上不属于 F 的另一条边 f （一定只有一条）。"}, {"k": "p", "x": "首先， f 的权值一定不会比 e 小，不然 f 会在 e 之前被选取。"}, {"k": "p", "x": "然后， f 的权值一定不会比 e 大，不然 T+e-f 就是一棵比 T 还优的生成树了。"}, {"k": "p", "x": "所以， T+e-f 包含了 F ，并且也是一棵最小生成树，归纳成立。"}, {"k": "h4", "x": "例题"}, {"k": "h4", "x": "口袋的天空"}, {"k": "p", "x": "有 n 朵云，你要将它们连成 k 个棉花糖，将 X[i] 云朵和 Y[i] 连接起来需要 L[i] 的代价，求最小代价。"}, {"k": "code", "x": "#include <algorithm>\n#include <iostream>\nusing namespace std;\n\nint fa[1010];  // 定义父亲\nint n, m, k;\n\nstruct edge {\nint u, v, w;\n};\n\nint l;\nedge g[10010];\n\nvoid add(int u, int v, int w) {\nl++;\ng[l].u = u;\ng[l].v = v;\ng[l].w = w;\n}\n\n// 标准并查集\nint findroot(int x) { return fa[x] == x ? x : fa[x] = findroot(fa[x]); }\n\nvoid Merge(int x, int y) {\nx = findroot(x);\ny = findroot(y);\nfa[x] = y;\n}\n\nbool cmp(edge A, edge B) { return A.w < B.w; }\n\n// Kruskal 算法\nvoid kruskal() {\nint tot = 0;  // 存已选了的边数\nint ans = 0;  // 存总的代价\nfor (int i = 1; i <= m; i++) {\nint xr = findroot(g[i].u), yr = findroot(g[i].v);\nif (xr != yr) {   // 如果父亲不一样\nMerge(xr, yr);  // 合并\ntot++;          // 边数增加\nans += g[i].w;  // 代价增加\n}\nif (tot >= (n - k)) {  // 检查选的边数是否满足 k 个棉花糖\ncout << ans << '\\n';\nreturn;\n}\n}\ncout << \"No Answer\\n\";  // 无法连成\n}\n\nint main() {\ncin >> n >> m >> k;\nfor (int i = 1; i <= n; i++) {  // 初始化\nfa[i] = i;\n}\nfor (int i = 1; i <= m; i++) {\nint u, v, w;\ncin >> u >> v >> w;\nadd(u, v, w);  // 添加边\n}\nsort(g + 1, g + m + 1, cmp);  // 先按边权排序\nkruskal();\nreturn 0;\n}"}, {"k": "h4", "x": "Prim 算法"}, {"k": "p", "x": "Prim 算法是另一种常见并且好写的最小生成树算法。该算法的基本思想是从一个结点开始，不断加点（而不是 Kruskal 算法的加边）。"}, {"k": "h4", "x": "实现"}, {"k": "p", "x": "图示："}, {"k": "p", "x": "具体来说，每次要选择距离最小的一个结点，以及用新的边更新其他结点的距离。"}, {"k": "p", "x": "其实跟 Dijkstra 算法一样，每次找到距离最小的一个点，可以暴力找也可以用堆维护。"}, {"k": "p", "x": "堆优化的方式类似 Dijkstra 的堆优化，但如果使用二叉堆等不支持 O(1) decrease-key 的堆，复杂度就不优于 Kruskal，常数也比 Kruskal 大。所以，一般情况下都使用 Kruskal 算法，在稠密图尤其是完全图上，暴力 Prim 的复杂度比 Kruskal 优，但 不一定 实际跑得更快。"}, {"k": "p", "x": "暴力： O(n^2+m) 。"}, {"k": "p", "x": "二叉堆： O((n+m) log n) 。"}, {"k": "p", "x": "Fib 堆： O(n log n + m) 。"}, {"k": "p", "x": "伪代码："}, {"k": "p", "x": "1 Input. The nodes of the graph V ; the function g(u, v) which"}, {"k": "p", "x": "means the weight of the edge (u, v); the function adj(v) which"}, {"k": "p", "x": "means the nodes adjacent to v."}, {"k": "p", "x": "2 Output. The sum of weights of the MST of the input graph."}, {"k": "p", "x": "3 Method."}, {"k": "h4", "x": "4 result <- 0"}, {"k": "p", "x": "5 choose an arbitrary node in V to be the root"}, {"k": "h4", "x": "6 dis(root) <- 0"}, {"k": "p", "x": "7 for each node v 属于 (V-root)"}, {"k": "p", "x": "8 dis(v) <- INF"}, {"k": "h4", "x": "9 rest <- V"}, {"k": "h4", "x": "10 while rest != 空集"}, {"k": "p", "x": "11 cur <- the node with the minimum dis in rest"}, {"k": "p", "x": "12 result <- result+dis(cur)"}, {"k": "h4", "x": "13 rest <- rest-cur"}, {"k": "h4", "x": "14 for each node v 属于 adj(cur)"}, {"k": "p", "x": "15 dis(v) <- min(dis(v), g(cur, v))"}, {"k": "h4", "x": "16 return result"}, {"k": "p", "x": "注意：上述代码只是求出了最小生成树的权值，如果要输出方案还需要记录每个点的 dis 代表的是哪条边。"}, {"k": "code", "x": "// 使用二叉堆优化的 Prim 算法。\n#include <cstring>\n#include <iostream>\n#include <queue>\nusing namespace std;\nconstexpr int N = 5050, M = 2e5 + 10;\n\nstruct E {\nint v, w, x;\n} e[M * 2];\n\nint n, m, h[N], cnte;\n\nvoid adde(int u, int v, int w) { e[++cnte] = E{v, w, h[u]}, h[u] = cnte; }\n\nstruct S {\nint u, d;\n};\n\nbool operator<(const S &x, const S &y) { return x.d > y.d; }\n\npriority_queue<S> q;\nint dis[N];\nbool vis[N];\n\nint res = 0, cnt = 0;\n\nvoid Prim() {\nmemset(dis, 0x3f, sizeof(dis));\ndis[1] = 0;\nq.push({1, 0});\nwhile (!q.empty()) {\nif (cnt >= n) break;\nint u = q.top().u, d = q.top().d;\nq.pop();\nif (vis[u]) continue;\nvis[u] = true;\n++cnt;\nres += d;\nfor (int i = h[u]; i; i = e[i].x) {\nint v = e[i].v, w = e[i].w;\nif (w < dis[v]) {\ndis[v] = w, q.push({v, w});\n}\n}\n}\n}\n\nint main() {\ncin >> n >> m;\nfor (int i = 1, u, v, w; i <= m; ++i) {\ncin >> u >> v >> w, adde(u, v, w), adde(v, u, w);\n}\nPrim();\nif (cnt == n)\ncout << res;\nelse\ncout << \"No MST.\";\nreturn 0;\n}"}, {"k": "h4", "x": "证明"}, {"k": "p", "x": "从任意一个结点开始，将结点分成两类：已加入的，未加入的。"}, {"k": "p", "x": "每次从未加入的结点中，找一个与已加入的结点之间边权最小值最小的结点。"}, {"k": "p", "x": "然后将这个结点加入，并连上那条边权最小的边。"}, {"k": "p", "x": "重复 n-1 次即可。"}, {"k": "p", "x": "证明：还是说明在每一步，都存在一棵最小生成树包含已选边集。"}, {"k": "p", "x": "基础：只有一个结点的时候，显然成立。"}, {"k": "p", "x": "归纳：如果某一步成立，当前边集为 F ，属于 T 这棵 MST，接下来要加入边 e 。"}, {"k": "p", "x": "如果 e 属于 T ，那么成立。"}, {"k": "p", "x": "否则考虑 T+e 中环上另一条可以加入当前边集的边 f 。"}, {"k": "p", "x": "首先， f 的权值一定不小于 e 的权值，否则就会选择 f 而不是 e 了。"}, {"k": "p", "x": "然后， f 的权值一定不大于 e 的权值，否则 T+e-f 就是一棵更小的生成树了。"}, {"k": "p", "x": "因此， e 和 f 的权值相等， T+e-f 也是一棵最小生成树，且包含了 F 。"}, {"k": "p", "x": "例题："}, {"k": "h4", "x": "Status"}, {"k": "p", "x": "Problem"}, {"k": "h4", "x": "Tags"}, {"k": "p", "x": "P3366"}, {"k": "p", "x": "."}, {"k": "p", "x": "【模板】最小生成树"}, {"k": "h4", "x": "图论"}, {"k": "p", "x": "P1194"}, {"k": "p", "x": "."}, {"k": "p", "x": "买礼物"}, {"k": "h4", "x": "图论"}, {"k": "p", "x": "P1265"}, {"k": "p", "x": "."}, {"k": "p", "x": "公路修建"}, {"k": "h4", "x": "图论"}, {"k": "p", "x": "P1340"}, {"k": "p", "x": "."}, {"k": "p", "x": "兽径管理"}, {"k": "h4", "x": "图论"}, {"k": "p", "x": "P2115"}, {"k": "p", "x": "."}, {"k": "p", "x": "Sabotage G"}, {"k": "h4", "x": "图论"}, {"k": "p", "x": "P2573"}, {"k": "p", "x": "."}, {"k": "p", "x": "滑雪"}, {"k": "h4", "x": "图论"}, {"k": "p", "x": "P3104"}, {"k": "p", "x": "."}, {"k": "p", "x": "Counting Friends G"}, {"k": "h4", "x": "图论"}, {"k": "h4", "x": "莫队算法"}, {"k": "h4", "x": "Floyd 最短路算法"}], "chars": 5041}, {"id": "graph-38", "title": "图论 02 · Floyd 最短路算法", "cat": "图论", "blocks": [{"k": "h4", "x": "最短路径定义"}, {"k": "p", "x": "在图论中，最短路径（Shortest Path）是指在带权图（有权值的图）中，从一个顶点（起点）到另一个顶点（终点）的路径中，边权之和最小的路径。严格定义如下："}, {"k": "p", "x": "设 G = (V, E, w) 为一个带权图（可以是有向图或无向图），其中："}, {"k": "li", "x": "V 是顶点集，"}, {"k": "li", "x": "E 是边集，"}, {"k": "li", "x": "w: E -> R 是边权函数（赋予每条边一个实数权重，可为正、负或零）。"}, {"k": "p", "x": "对于顶点 u, v 属于 V ，从 u 到 v 的一条路径 P = (v[0], v[1], …, v[k]) （其中 v[0] = u , v[k] = v ）的权重（或长度）为该路径所有边权之和："}, {"k": "p", "x": "w(P) = sum _(i=1)^(k) w(v[i-1], v[i])."}, {"k": "p", "x": "若存在一条路径 P^ ，使得对于所有从 u 到 v 的路径 P ，都有 w(P^) <= w(P) ，则称 P^ 为从 u 到 v 的最短路径*。"}, {"k": "h4", "x": "Floyd 算法"}, {"k": "p", "x": "Floyd 算法又称为插点法，是一种利用动态规划的思想寻找给定的加权图中多源点之间最短路径的算法。"}, {"k": "p", "x": "作用：求任意两个结点之间的最短路。"}, {"k": "p", "x": "复杂度比较高，但是常数小，容易实现（只有三个 for）。"}, {"k": "p", "x": "适用于任何图，不管有向无向，边权正负，但是最短路必须存在。（不能有负环）"}, {"k": "h4", "x": "实现"}, {"k": "p", "x": "我们定义一个数组 f[k][x][y]，表示只允许经过结点 1 到 k （也就是说，在子图 V'=1, 2, …, k 中的路径，注意， x 与 y 不一定在这个子图中），结点 x 到结点 y 的最短路长度。"}, {"k": "p", "x": "很显然，f[n][x][y] 就是结点 x 到结点 y 的最短路长度（因为 V'=1, 2, …, n 即为 V 本身，其表示的最短路径就是所求路径）。"}, {"k": "p", "x": "接下来考虑如何求出 f 数组的值。"}, {"k": "p", "x": "f[0][x][y]： x 与 y 的边权，或者 0 ，或者 + INF （f[0][x][y] 什么时候应该是 + INF ？当 x 与 y 间有直接相连的边的时候，为它们的边权；当 x = y 的时候为零，因为到本身的距离为零；当 x 与 y 没有直接相连的边的时候，为 + INF ）。"}, {"k": "p", "x": "f[k][x][y] = min(f[k-1][x][y], f[k-1][x][k]+f[k-1][k][y])（f[k-1][x][y]，为不经过 k 点的最短路径，而 f[k-1][x][k]+f[k-1][k][y]，为经过了 k 点的最短路）。"}, {"k": "p", "x": "上面两行都显然是对的，所以说这个做法空间是 O(N^3) ，我们需要依次增加问题规模（ k 从 1 到 n ），判断任意两点在当前问题规模下的最短路。"}, {"k": "code", "x": "for (k = 1; k <= n; k++) {\nfor (x = 1; x <= n; x++) {\nfor (y = 1; y <= n; y++) {\nf[k][x][y] = min(f[k - 1][x][y], f[k - 1][x][k] + f[k - 1][k][y]);\n}\n}\n}"}, {"k": "h4", "x": "图示"}, {"k": "p", "x": "1，从任意一条单边路径开始。所有两点之间的距离是边的权，如果两点之间没有边相连，则权为无穷大。"}, {"k": "p", "x": "现在我们要寻找到每两点之间的最小路径，如下图所示。"}, {"k": "p", "x": "首先把图转化为一个二维数组，这个二维数组就是每条边的权重。权重的大小就是他们之间的路径距离。"}, {"k": "h4", "x": "2.加点"}, {"k": "p", "x": "第二步就是循环加点，这里我们首先加入点①。加入①后，本部相通的②与④之间就有了一条路径，长度为 （1+5）= 6 < INF ，所以就要进行更新。"}, {"k": "p", "x": "加入①后还影响了②与⑥的连接，他们之间又多了一条路径，这时也需要比较 1 + 9 < 8，所以②与⑥的最短路径保持原来的不变，不进行更新。"}, {"k": "p", "x": "继续加入节点②,由于②本身的基础连接比较多，所以影响的路径更多，这里在图中就不一一的详细标明。"}, {"k": "p", "x": "①与③ = 1+1 //2"}, {"k": "p", "x": "③与④ = 1+6 //7"}, {"k": "p", "x": "③与⑥ = 1+8 //9"}, {"k": "p", "x": "...."}, {"k": "p", "x": "除了这些原来未连通的新增的路径外，不要忘记若有原路径的需要比较（当然，程序是不是忘记的，毕竟是一个 for 循环）。"}, {"k": "p", "x": "重复上面的操作，知道每个点都加入后，那么最终得到的就是一个每个点亮亮之间最短的路径了。"}, {"k": "h4", "x": "优化"}, {"k": "p", "x": "因为第一维对结果无影响，我们可以发现数组的第一维是可以省略的，于是可以直接改成 f[x][y] = min(f[x][y], f[x][k]+f[k][y])。"}, {"k": "h4", "x": "证明第一维对结果无影响"}, {"k": "p", "x": "对于给定的 k，当更新 f[k][x][y] 时，涉及的元素总是来自 f[k-1] 数组的第 k 行和第 k 列。然后我们可以发现，对于给定的 k，当更新 f[k][k][y] 或 f[k][x][k]，总是不会发生数值更新，因为按照公式 f[k][k][y] = min(f[k-1][k][y], f[k-1][k][k]+f[k-1][k][y]),f[k-1][k][k] 为 0，因此这个值总是 f[k-1][k][y]，对于 f[k][x][k] 的证明类似。"}, {"k": "p", "x": "因此，如果省略第一维，在给定的 k 下，每个元素的更新中使用到的元素都没有在这次迭代中更新，因此第一维的省略并不会影响结果。"}, {"k": "code", "x": "for (k = 1; k <= n; k++) {\nfor (x = 1; x <= n; x++) {\nfor (y = 1; y <= n; y++) {\nf[x][y] = min(f[x][y], f[x][k] + f[k][y]);\n}\n}\n}"}, {"k": "p", "x": "综上时间复杂度是 O(N^3) ，空间复杂度是 O(N^2) 。"}, {"k": "p", "x": "例题："}, {"k": "h4", "x": "Status"}, {"k": "p", "x": "Problem"}, {"k": "h4", "x": "Tags"}, {"k": "p", "x": "P3416"}, {"k": "p", "x": "."}, {"k": "p", "x": "Moocast S"}, {"k": "h4", "x": "图论"}, {"k": "p", "x": "P8186"}, {"k": "p", "x": "."}, {"k": "p", "x": "Redistributing Gifts S"}, {"k": "h4", "x": "图论"}, {"k": "p", "x": "P5839"}, {"k": "p", "x": "."}, {"k": "p", "x": "Moortal Cowmbat G"}, {"k": "h4", "x": "图论"}, {"k": "h4", "x": "最小生成树"}, {"k": "h4", "x": "Bellman-Ford 与 SPFA 算法"}], "chars": 2351}, {"id": "graph-39", "title": "图论 03 · Bellman-Ford 与 SPFA 算法", "cat": "图论", "blocks": [{"k": "h4", "x": "Bellman–Ford 算法"}, {"k": "p", "x": "Bellman–Ford 算法是一种基于松弛（relax）操作的最短路算法，可以求出有负权的图的最短路，并可以对最短路不存在的情况进行判断。"}, {"k": "p", "x": "在国内 OI 界，你可能听说过的「SPFA」，就是 Bellman–Ford 算法的一种实现。"}, {"k": "h4", "x": "过程"}, {"k": "p", "x": "先介绍 Bellman–Ford 算法要用到的松弛操作（Dijkstra 算法也会用到松弛操作）。"}, {"k": "p", "x": "对于边 (u,v) ，松弛操作对应下面的式子： dis(v) = min(dis(v), dis(u) + w(u, v)) 。"}, {"k": "p", "x": "这么做的含义是显然的：我们尝试用 S -> u -> v （其中 S -> u 的路径取最短路）这条路径去更新 v 点最短路的长度，如果这条路径更优，就进行更新。"}, {"k": "p", "x": "Bellman–Ford 算法所做的，就是不断尝试对图上每一条边进行松弛。我们每进行一轮循环，就对图上所有的边都尝试进行一次松弛操作，当一次循环中没有成功的松弛操作时，算法停止。"}, {"k": "p", "x": "每次循环是 O(m) 的，那么最多会循环多少次呢？"}, {"k": "p", "x": "在最短路存在的情况下，由于一次松弛操作会使最短路的边数至少 +1 ，而最短路的边数最多为 n-1 ，因此整个算法最多执行 n-1 轮松弛操作。故总时间复杂度为 O(nm) 。"}, {"k": "p", "x": "但还有一种情况，如果从 S 点出发，抵达一个负环时，松弛操作会无休止地进行下去。注意到前面的论证中已经说明了，对于最短路存在的图，松弛操作最多只会执行 n-1 轮，因此如果第 n 轮循环时仍然存在能松弛的边，说明从 S 点出发，能够抵达一个负环。"}, {"k": "h4", "x": "负环判断中存在的常见误区"}, {"k": "p", "x": "需要注意的是，以 S 点为源点跑 Bellman–Ford 算法时，如果没有给出存在负环的结果，只能说明从 S 点出发不能抵达一个负环，而不能说明图上不存在负环。"}, {"k": "p", "x": "因此如果需要判断整个图上是否存在负环，最严谨的做法是建立一个超级源点，向图上每个节点连一条权值为 0 的边，然后以超级源点为起点执行 Bellman–Ford 算法。"}, {"k": "h4", "x": "实现"}, {"k": "code", "x": "struct Edge {\nint u, v, w;\n};\n\nvector<Edge> edge;\n\nint dis[MAXN], u, v, w;\nconstexpr int INF = 0x3f3f3f3f;\n\nbool bellmanford(int n, int s) {\nmemset(dis, 0x3f, (n + 1) * sizeof(int));\ndis[s] = 0;\nbool flag = false;  // 判断一轮循环过程中是否发生松弛操作\nfor (int i = 1; i <= n; i++) {\nflag = false;\nfor (int j = 0; j < edge.size(); j++) {\nu = edge[j].u, v = edge[j].v, w = edge[j].w;\nif (dis[u] == INF) continue;\n// 无穷大与常数加减仍然为无穷大\n// 因此最短路长度为 INF 的点引出的边不可能发生松弛操作\nif (dis[v] > dis[u] + w) {\ndis[v] = dis[u] + w;\nflag = true;\n}\n}\n// 没有可以松弛的边时就停止算法\nif (!flag) {\nbreak;\n}\n}\n// 第 n 轮循环仍然可以松弛时说明 s 点可以抵达一个负环\nreturn flag;\n}"}, {"k": "p", "x": "队列优化：SPFA"}, {"k": "p", "x": "即 Shortest Path Faster Algorithm。"}, {"k": "p", "x": "很多时候我们并不需要那么多无用的松弛操作。"}, {"k": "p", "x": "很显然，只有上一次被松弛的结点，所连接的边，才有可能引起下一次的松弛操作。"}, {"k": "p", "x": "那么我们用队列来维护「哪些结点可能会引起松弛操作」，就能只访问必要的边了。"}, {"k": "p", "x": "SPFA 也可以用于判断 s 点是否能抵达一个负环，只需记录最短路经过了多少条边，当经过了至少 n 条边时，说明 s 点可以抵达一个负环。"}, {"k": "code", "x": "struct edge {\nint v, w;\n};\n\nvector<edge> e[MAXN];\nint dis[MAXN], cnt[MAXN], vis[MAXN];\nqueue<int> q;\n\nbool spfa(int n, int s) {\nmemset(dis, 0x3f, (n + 1) * sizeof(int));\ndis[s] = 0, vis[s] = 1;\nq.push(s);\nwhile (!q.empty()) {\nint u = q.front();\nq.pop(), vis[u] = 0;\nfor (auto ed : e[u]) {\nint v = ed.v, w = ed.w;\nif (dis[v] > dis[u] + w) {\ndis[v] = dis[u] + w;\ncnt[v] = cnt[u] + 1;  // 记录最短路经过的边数\nif (cnt[v] >= n) return false;\n// 在不经过负环的情况下，最短路至多经过 n - 1 条边\n// 因此如果经过了多于 n 条边，一定说明经过了负环\nif (!vis[v]) q.push(v), vis[v] = 1;\n}\n}\n}\nreturn true;\n}"}, {"k": "p", "x": "虽然在大多数情况下 SPFA 跑得很快，但其最坏情况下的时间复杂度为 O(nm) ，将其卡到这个复杂度也是不难的，所以考试时要谨慎使用（在没有负权边时最好使用 Dijkstra 算法，在有负权边且题目中的图没有特殊性质时，若 SPFA 是标算的一部分，题目不应当给出 Bellman–Ford 算法无法通过的数据范围）。"}, {"k": "p", "x": "例题："}, {"k": "h4", "x": "Status"}, {"k": "p", "x": "Problem"}, {"k": "h4", "x": "Tags"}, {"k": "p", "x": "P3385"}, {"k": "p", "x": "."}, {"k": "p", "x": "【模板】负环"}, {"k": "h4", "x": "图论"}, {"k": "p", "x": "P3371"}, {"k": "p", "x": "."}, {"k": "p", "x": "【模板】单源最短路径（弱化版）"}, {"k": "h4", "x": "图论"}, {"k": "p", "x": "P2850"}, {"k": "p", "x": "."}, {"k": "p", "x": "Wormholes G"}, {"k": "h4", "x": "图论"}, {"k": "p", "x": "Floyd 最短路算法"}, {"k": "h4", "x": "Dijkstra 算法"}], "chars": 2435}, {"id": "graph-40", "title": "图论 04 · Dijkstra 算法", "cat": "图论", "blocks": [{"k": "h4", "x": "Dijkstra 算法"}, {"k": "p", "x": "Dijkstra（/'dikstra/或/'deikstra/）算法由荷兰计算机科学家 E. W. Dijkstra 于 1956 年发现，1959 年公开发表。是一种求解 非负权图 上单源最短路径的算法。"}, {"k": "h4", "x": "过程"}, {"k": "p", "x": "将结点分成两个集合：已确定最短路长度的点集（记为 S 集合）的和未确定最短路长度的点集（记为 T 集合）。一开始所有的点都属于 T 集合。"}, {"k": "p", "x": "初始化 dis(s)=0 ，其他点的 dis 均为 + INF 。"}, {"k": "p", "x": "然后重复这些操作："}, {"k": "li", "x": "从 T 集合中，选取一个最短路长度最小的结点，移到 S 集合中。"}, {"k": "li", "x": "对那些刚刚被加入 S 集合的结点的所有出边执行松弛操作。"}, {"k": "p", "x": "直到 T 集合为空，算法结束。"}, {"k": "h4", "x": "时间复杂度"}, {"k": "p", "x": "朴素的实现方法为每次 2 操作执行完毕后，直接在 T 集合中暴力寻找最短路长度最小的结点。2 操作总时间复杂度为 O(m) ，1 操作总时间复杂度为 O(n^2) ，全过程的时间复杂度为 O(n^2 + m) = O(n^2) 。"}, {"k": "p", "x": "可以用堆来优化这一过程：每成功松弛一条边 (u,v) ，就将 v 插入堆中（如果 v 已经在堆中，直接执行 Decrease-key），1 操作直接取堆顶结点即可。共计 O(m) 次 Decrease-key， O(n) 次 pop，选择不同堆可以取到不同的复杂度，参考堆页面。堆优化能做到的最优复杂度为 O(nlog n+m) ，能做到这一复杂度的有斐波那契堆等。"}, {"k": "p", "x": "特别地，可以使用优先队列维护，此时无法执行 Decrease-key 操作，但可以通过每次松弛时重新插入该结点，且弹出时检查该结点是否已被松弛过，若是则跳过，复杂度 O(mlog n) ，优点是实现较简单。"}, {"k": "p", "x": "这里的堆也可以用线段树来实现，复杂度为 O(mlog n) ，在一些特殊的非递归线段树实现下，该做法常数比堆更小。并且线段树支持的操作更多，在一些特殊图问题上只能用线段树来维护。"}, {"k": "p", "x": "在稀疏图中， m = O(n) ，堆优化的 Dijkstra 算法具有较大的效率优势；而在稠密图中， m = O(n^2) ，这时候使用朴素实现更优。"}, {"k": "h4", "x": "实现"}, {"k": "p", "x": "这里同时给出 O(n^2) 的暴力做法实现和 O(m log m) 的优先队列做法实现。"}, {"k": "h4", "x": "朴素实现"}, {"k": "code", "x": "struct edge {\nint v, w;\n};"}, {"k": "p", "x": "vector<edge> e[MAXN];\nint dis[MAXN], vis[MAXN];"}, {"k": "code", "x": "void dijkstra(int n, int s) {\nmemset(dis, 0x3f, (n + 1) * sizeof(int));\ndis[s] = 0;\nfor (int i = 1; i <= n; i++) {\nint u = 0, mind = 0x3f3f3f3f;\nfor (int j = 1; j <= n; j++)\nif (!vis[j] && dis[j] < mind) u = j, mind = dis[j];\nvis[u] = true;\nfor (auto ed : e[u]) {\nint v = ed.v, w = ed.w;\nif (dis[v] > dis[u] + w) dis[v] = dis[u] + w;\n}\n}\n}"}, {"k": "h4", "x": "优先队列实现"}, {"k": "code", "x": "struct edge {\nint v, w;\n};"}, {"k": "code", "x": "struct node {\nint dis, u;"}, {"k": "code", "x": "bool operator>(const node& a) const { return dis > a.dis; }\n};"}, {"k": "p", "x": "vector<edge> e[MAXN];\nint dis[MAXN], vis[MAXN];\npriority_queue<node, vector<node>, greater<node>> q;"}, {"k": "code", "x": "void dijkstra(int n, int s) {\nmemset(dis, 0x3f, (n + 1) * sizeof(int));\nmemset(vis, 0, (n + 1) * sizeof(int));\ndis[s] = 0;\nq.push({0, s});\nwhile (!q.empty()) {\nint u = q.top().u;\nq.pop();\nif (vis[u]) continue;\nvis[u] = 1;\nfor (auto ed : e[u]) {\nint v = ed.v, w = ed.w;\nif (dis[v] > dis[u] + w) {\ndis[v] = dis[u] + w;\nq.push({dis[v], v});\n}\n}\n}\n}"}, {"k": "p", "x": "例题："}, {"k": "h4", "x": "Status"}, {"k": "p", "x": "Problem"}, {"k": "h4", "x": "Tags"}, {"k": "p", "x": "P4779"}, {"k": "p", "x": "."}, {"k": "p", "x": "【模板】单源最短路径（标准版）"}, {"k": "h4", "x": "图论"}, {"k": "p", "x": "P1119"}, {"k": "p", "x": "."}, {"k": "p", "x": "灾后重建"}, {"k": "h4", "x": "图论"}, {"k": "p", "x": "P1462"}, {"k": "p", "x": "."}, {"k": "p", "x": "通往奥格瑞玛的道路"}, {"k": "h4", "x": "图论"}, {"k": "p", "x": "P1608"}, {"k": "p", "x": "."}, {"k": "p", "x": "路径统计"}, {"k": "h4", "x": "图论"}, {"k": "p", "x": "P1772"}, {"k": "p", "x": "."}, {"k": "p", "x": "物流运输"}, {"k": "h4", "x": "图论"}, {"k": "p", "x": "P2371"}, {"k": "p", "x": "."}, {"k": "p", "x": "墨墨的等式"}, {"k": "h4", "x": "图论"}, {"k": "p", "x": "Bellman-Ford 与 SPFA 算法"}, {"k": "h4", "x": "拓扑排序与 Kahn 算法"}], "chars": 2042}, {"id": "graph-41", "title": "图论 05 · 拓扑排序与 Kahn 算法", "cat": "图论", "blocks": [{"k": "h4", "x": "定义"}, {"k": "p", "x": "拓扑排序（Topological sorting）要解决的问题是如何给一个有向无环图的所有节点排序。"}, {"k": "p", "x": "我们可以拿大学每学期排课的例子来描述这个过程，比如学习大学课程中有：「程序设计」，「算法语言」，「高等数学」，「离散数学」，「编译技术」，「普通物理」，「数据结构」，「数据库系统」等。按照例子中的排课，当我们想要学习「数据结构」的时候，就必须先学会「离散数学」，学习完这门课后就获得了学习「编译技术」的前置条件。当然，「编译技术」还有一个更加前的课程「算法语言」。这些课程就相当于几个顶点 u , 顶点之间的有向边 (u,v) 就相当于学习课程的顺序。教务处安排这些课程，使得在逻辑关系符合的情况下排出课表，就是拓扑排序的过程。"}, {"k": "p", "x": "但是如果某一天排课的老师打瞌睡了，说想要学习数据结构，还得先学操作系统，而操作系统的前置课程又是数据结构，那么到底应该先学哪一个（不考虑同时学习的情况）？在这里，数据结构和操作系统间就出现了一个环，显然同学们现在没办法弄清楚自己需要先学什么了，也就没办法进行拓扑排序了。因为如果有向图中存在环路，那么我们就没办法进行拓扑排序。"}, {"k": "p", "x": "因此我们可以说在一个 DAG（有向无环图）中，我们将图中的顶点以线性方式进行排序，使得对于任何的顶点 u 到 v 的有向边 (u,v) , 都可以有 u 在 v 的前面。"}, {"k": "p", "x": "还有给定一个 DAG，如果从 i 到 j 有边，则认为 j 依赖于 i 。如果 i 到 j 有路径（ i 可达 j ），则称 j 间接依赖于 i 。"}, {"k": "p", "x": "拓扑排序的目标是将所有节点排序，使得排在前面的节点不能依赖于排在后面的节点。"}, {"k": "h4", "x": "Kahn 算法"}, {"k": "h4", "x": "构造拓扑序列步骤"}, {"k": "li", "x": "从图中选择一个入度为零的点。"}, {"k": "li", "x": "输出该顶点，从图中删除此顶点及其所有的出边。"}, {"k": "p", "x": "重复上面两步，直到所有顶点都输出，拓扑排序完成，或者图中不存在入度为零的点，此时说明图是有环图，拓扑排序无法完成，陷入死锁。"}, {"k": "h4", "x": "过程"}, {"k": "p", "x": "初始状态下，集合 S 装着所有入度为 0 的点， L 是一个空列表。"}, {"k": "p", "x": "每次从 S 中取出一个点 u （可以随便取）放入 L , 然后将 u 的所有边 (u, v[1]), (u, v[2]), (u, v[3]) ... 删除。对于边 (u, v) ，若将该边删除后点 v 的入度变为 0 ，则将 v 放入 S 中。"}, {"k": "p", "x": "不断重复以上过程，直到集合 S 为空。检查图中是否存在任何边，如果有，那么这个图一定有环路，否则返回 L ， L 中顶点的顺序就是构造拓扑序列的结果。"}, {"k": "p", "x": "代码的核心是维持一个入度为 0 的顶点的集合。"}, {"k": "h4", "x": "可以参考该图"}, {"k": "p", "x": "对其排序的结果就是：2 -> 8 -> 0 -> 3 -> 7 -> 1 -> 5 -> 6 -> 9 -> 4 -> 11 -> 10 -> 12"}, {"k": "h4", "x": "时间复杂度"}, {"k": "p", "x": "假设这个图 G = (V, E) 在初始化入度为 0 的集合 S 的时候就需要遍历整个图，并检查每一条边，因而有 O(E+V) 的复杂度。然后对该集合进行操作，显然也是需要 O(E+V) 的时间复杂度。"}, {"k": "p", "x": "因而总的时间复杂度就有 O(E+V)"}, {"k": "h4", "x": "实现"}, {"k": "code", "x": "int n, m;\nvector<int> G[MAXN];\nint in[MAXN];  // 存储每个结点的入度\n\nbool toposort() {\nvector<int> L;\nqueue<int> S;\nfor (int i = 1; i <= n; i++)\nif (in[i] == 0) S.push(i);\nwhile (!S.empty()) {\nint u = S.front();\nS.pop();\nL.push_back(u);\nfor (auto v : G[u]) {\nif (--in[v] == 0) {\nS.push(v);\n}\n}\n}\nif (L.size() == n) {\nfor (auto i : L) cout << i << ' ';\nreturn true;\n}\nreturn false;\n}"}, {"k": "p", "x": "例题："}, {"k": "h4", "x": "Status"}, {"k": "p", "x": "Problem"}, {"k": "h4", "x": "Tags"}, {"k": "p", "x": "B3644"}, {"k": "p", "x": "."}, {"k": "p", "x": "【模板】拓扑排序 / 家谱树"}, {"k": "h4", "x": "图论"}, {"k": "p", "x": "P1347"}, {"k": "p", "x": "."}, {"k": "p", "x": "排序"}, {"k": "h4", "x": "图论"}, {"k": "p", "x": "P1038"}, {"k": "p", "x": "."}, {"k": "p", "x": "神经网络"}, {"k": "h4", "x": "图论"}, {"k": "p", "x": "P1983"}, {"k": "p", "x": "."}, {"k": "p", "x": "车站分级"}, {"k": "h4", "x": "图论"}, {"k": "p", "x": "Dijkstra 算法"}, {"k": "h4", "x": "欧拉路"}], "chars": 1715}, {"id": "graph-42", "title": "图论 06 · 欧拉路", "cat": "图论", "blocks": [{"k": "h4", "x": "欧拉路径定义"}, {"k": "p", "x": "通过图中所有边恰好一次且行遍所有顶点（允许多次经过同一个点）的通路称为欧拉路径。即一笔画。"}, {"k": "p", "x": "如果这条路径的起点和终点重合，那么就是欧拉回路。"}, {"k": "p", "x": "如何判断图是否有欧拉回路或者欧拉路径？"}, {"k": "p", "x": "无向图：因为欧拉路径中，除了起点与终点以外，任意点的“进”“出”次数相等，所以除了两个点为奇点（度数为奇数的点）（终点和起点）以外，其它点的度数均为偶数。"}, {"k": "p", "x": "如果是欧拉回路，奇点的个数应该为 0。"}, {"k": "p", "x": "有向图：欧拉路径中，最多只有两个点的入度不等于出度。起点出度比入度大 1，终点入度比出度大 1。"}, {"k": "p", "x": "如果是欧拉回路，所有点的入度 = 出度。"}, {"k": "h4", "x": "Hierholzer 算法"}, {"k": "p", "x": "Hierholzer 算法用于寻找欧拉回路，在找不到欧拉回路的情况下会找到欧拉路径。"}, {"k": "p", "x": "算法流程："}, {"k": "p", "x": "对于无向图："}, {"k": "p", "x": "1、判断奇点数。奇点数若为 0 则任意指定起点，奇点数若为 2 则指定起点为奇点。"}, {"k": "p", "x": "2、开始递归函数 Hierholzer(x):"}, {"k": "p", "x": "循环寻找与 x 相连的边 x -> u:"}, {"k": "p", "x": "删除 x -> u"}, {"k": "h4", "x": "删除 u -> x"}, {"k": "h4", "x": "Hierholzer(u);"}, {"k": "p", "x": "回溯时将 x 插入答案队列之中"}, {"k": "p", "x": "3、倒序输出答案队列"}, {"k": "p", "x": "对于有向图："}, {"k": "p", "x": "1、判断顶点入度与出度："}, {"k": "p", "x": "若所有顶点入度等于出度 -> 任意指定起点；"}, {"k": "p", "x": "若恰有一个顶点出度=入度 +1（起点），另一顶点入度=出度 +1（终点） -> 指定起点为前者；"}, {"k": "p", "x": "其他情况 -> 不存在欧拉路径/回路。"}, {"k": "p", "x": "2、开始递归函数 Hierholzer(x)："}, {"k": "p", "x": "循环寻找与 x 相连的出边 x -> u："}, {"k": "p", "x": "删除出边 x -> u（从邻接表中移除 u）；"}, {"k": "p", "x": "Hierholzer(u)；"}, {"k": "p", "x": "回溯时将 x 插入答案队列之中。"}, {"k": "p", "x": "3、倒序输出答案队列。"}, {"k": "h4", "x": "示例"}, {"k": "p", "x": "对于该图，算法的执行流程如下："}, {"k": "p", "x": "step1: 找到该图没有奇点，从 1 开始进行 Hierholzer 算法。"}, {"k": "p", "x": "step2: 删边 1 -> 2 递归到 2"}, {"k": "p", "x": "step3: 删边 2 -> 3 递归到 3"}, {"k": "p", "x": "step4: 删边 3 -> 7 递归到 7"}, {"k": "p", "x": "step5: 删边 7 -> 1 递归到 1"}, {"k": "p", "x": "step6: 1 无边，1 加入队列，返回"}, {"k": "p", "x": "step7: 7 加入队列，返回"}, {"k": "p", "x": "step8: 删边 3 -> 4 递归到 4"}, {"k": "h4", "x": "step9: 删边 4 -> 5 递归到 5"}, {"k": "p", "x": "step10: 删边 5 -> 6 递归到 6"}, {"k": "p", "x": "step11: 删边 6 -> 3 递归到 3"}, {"k": "p", "x": "step12: 3 加入队列，返回"}, {"k": "p", "x": "step13: 6 加入队列，返回"}, {"k": "p", "x": "step14: 5 加入队列，返回"}, {"k": "p", "x": "step15: 4 加入队列，返回"}, {"k": "p", "x": "step16: 3 加入队列，返回"}, {"k": "p", "x": "step17: 2 加入队列，返回"}, {"k": "p", "x": "step18: 1 加入队列，返回"}, {"k": "p", "x": "答案队列为：1 7 3 6 5 4 3 2 1。反向输出即为答案。"}, {"k": "h4", "x": "示例代码"}, {"k": "code", "x": "#include<bits/stdc++.h> //万能头文件\nusing namespace std;\n\nstruct node{\nint u;\nbool vis;  //记录是否被访问过\n};\nint n,m;\n\nvector<node> v[100010];\nint in[100010],st[100010]; //in 表示每个结点入度与出度的差（即入读 - 出度）\n\nstack<int> s;  //记录答案\n\nvoid dfs(int x){\nfor(int i=0;i<v[x].size();i=max(i+1,st[x])){\nif(v[x][i].vis) continue;\nv[x][i].vis=1;\nst[x]=i+1;\ndfs(v[x][i].u);\n}\ns.push(x);\n}\n\nbool cmp(node a,node b){\nreturn a.u<b.u;\n}\n\nint main(){\n\ncin>>n>>m;\nfor(int i=1,x,y;i<=m;i++){\ncin>>x>>y;\nv[x].push_back(node{y,0});\nin[y]++;\nin[x]--;\n}\n\nint fb=0,fe=0,pb=1,pe;\nfor(int i=1;i<=n;i++){  //判断是否存在欧拉路径\nif(in[i]>1||in[i]<-1) {\nprintf(\"No\");\nreturn 0;\n}\nif(in[i]==1) fe++,pe=i;\nif(in[i]==-1) fb++,pb=i;\nif(fb>1||fe>1) {\nprintf(\"No\");\nreturn 0;\n}\n}\n\nfor(int i=1;i<=n;i++) sort(v[i].begin(),v[i].end(),cmp);\n\ndfs(pb);\n\nwhile(s.size()){\nprintf(\"%d \",s.top());\ns.pop();\n}\nreturn 0;\n}"}, {"k": "p", "x": "例题："}, {"k": "h4", "x": "Status"}, {"k": "p", "x": "Problem"}, {"k": "h4", "x": "Tags"}, {"k": "p", "x": "P7771"}, {"k": "p", "x": "."}, {"k": "p", "x": "【模板】欧拉路径"}, {"k": "h4", "x": "图论"}, {"k": "p", "x": "P1333"}, {"k": "p", "x": "."}, {"k": "p", "x": "瑞瑞的木棍"}, {"k": "h4", "x": "图论"}, {"k": "p", "x": "P1341"}, {"k": "p", "x": "."}, {"k": "p", "x": "无序字母对"}, {"k": "h4", "x": "图论"}, {"k": "p", "x": "P2731"}, {"k": "p", "x": "."}, {"k": "p", "x": "骑马修栅栏"}, {"k": "h4", "x": "图论"}, {"k": "h4", "x": "拓扑排序与 Kahn 算法"}, {"k": "h4", "x": "强连通分量与 Tarjan 算法"}], "chars": 2059}, {"id": "graph-43", "title": "图论 07 · 强连通分量与 Tarjan 算法", "cat": "图论", "blocks": [{"k": "h4", "x": "定义"}, {"k": "p", "x": "强连通的定义是：有向图 G 强连通是指，G 中任意两个结点连通。"}, {"k": "p", "x": "强连通分量（Strongly Connected Components，SCC）的定义是：极大的强连通子图。"}, {"k": "p", "x": "这里要介绍的是如何来求强连通分量。"}, {"k": "p", "x": "Tarjan 算法"}, {"k": "h4", "x": "引入"}, {"k": "p", "x": "Robert E. Tarjan（罗伯特·塔扬，1948~），生于美国加州波莫纳，计算机科学家。"}, {"k": "p", "x": "Tarjan 发明了很多算法和数据结构。不少他发明的算法都以他的名字命名，以至于有时会让人混淆几种不同的算法。比如求各种连通分量的 Tarjan 算法，求 LCA（Lowest Common Ancestor，最近公共祖先）的 Tarjan 算法。并查集、Splay、Toptree 也是 Tarjan 发明的。"}, {"k": "p", "x": "我们这里要介绍的是在有向图中求强连通分量的 Tarjan 算法。"}, {"k": "h4", "x": "DFS 生成树"}, {"k": "p", "x": "在介绍该算法之前，先来了解 DFS 生成树，我们以下面的有向图为例："}, {"k": "p", "x": "有向图的 DFS 生成树主要有 4 种边（不一定全部出现）："}, {"k": "li", "x": "树边（tree edge）：示意图中以黑色边表示，每次搜索找到一个还没有访问过的结点的时候就形成了一条树边。"}, {"k": "li", "x": "反祖边（back edge）：示意图中以红色边表示（即 7 -> 1 ），也被叫做回边，即指向祖先结点的边。"}, {"k": "li", "x": "横叉边（cross edge）：示意图中以蓝色边表示（即 9 -> 7 ），它主要是在搜索的时候遇到了一个已经访问过的结点，但是这个结点 并不是 当前结点的祖先。"}, {"k": "li", "x": "前向边（forward edge）：示意图中以绿色边表示（即 3 -> 6 ），它是在搜索的时候遇到子树中的结点的时候形成的。"}, {"k": "p", "x": "我们考虑 DFS 生成树与强连通分量之间的关系。"}, {"k": "p", "x": "如果结点 u 是某个强连通分量在搜索树中遇到的第一个结点，那么这个强连通分量的其余结点肯定是在搜索树中以 u 为根的子树中。结点 u 被称为这个强连通分量的根。"}, {"k": "p", "x": "反证法：假设有个结点 v 在该强连通分量中但是不在以 u 为根的子树中，那么 u 到 v 的路径中肯定有一条离开子树的边。但是这样的边只可能是横叉边或者反祖边，然而这两条边都要求指向的结点已经被访问过了，这就和 v 不在以 u 为根的子树中矛盾了。得证。"}, {"k": "h4", "x": "Tarjan 算法求强连通分量"}, {"k": "p", "x": "Tarjan 算法基于对图进行深度优先搜索。我们视每个连通分量为搜索树中的一棵子树，在搜索过程中，维护一个栈，每次把搜索树中尚未处理的节点加入栈中。"}, {"k": "p", "x": "在 Tarjan 算法中为每个结点 u 维护了以下几个变量："}, {"k": "li", "x": "dfn_(u) ：深度优先搜索遍历时结点 u 被搜索的次序。"}, {"k": "li", "x": "low_(u) ：在 u 的子树中能够回溯到的最早的已经在栈中的结点。设以 u 为根的子树为 Subtree_(u) 。 low_(u) 定义为以下结点的 dfn 的最小值： Subtree_(u) 中的结点；从 Subtree_(u) 通过一条不在搜索树上的边能到达的结点。"}, {"k": "p", "x": "一个结点的子树内结点的 dfn 都大于该结点的 dfn。"}, {"k": "p", "x": "从根开始的一条路径上的 dfn 严格递增，low 严格非降。"}, {"k": "p", "x": "按照深度优先搜索算法搜索的次序对图中所有的结点进行搜索，维护每个结点的 dfn 与 low 变量，且让搜索到的结点入栈。每当找到一个强连通元素，就按照该元素包含结点数目让栈中元素出栈。在搜索过程中，对于结点 u 和与其相邻的结点 v （ v 不是 u 的父节点）考虑 3 种情况："}, {"k": "li", "x": "v 未被访问：继续对 v 进行深度搜索。在回溯过程中，用 low_(v) 更新 low_(u) 。因为存在从 u 到 v 的直接路径，所以 v 能够回溯到的已经在栈中的结点， u 也一定能够回溯到。"}, {"k": "li", "x": "v 被访问过，已经在栈中：根据 low 值的定义，用 dfn_(v) 更新 low_(u) 。"}, {"k": "li", "x": "v 被访问过，已不在栈中：说明 v 已搜索完毕，其所在连通分量已被处理，所以不用对其做操作。"}, {"k": "p", "x": "将上述算法写成伪代码："}, {"k": "p", "x": "TARJAN_SEARCH(int u)\nvis[u]=true\nlow[u]=dfn[u]=++dfncnt\npush u to the stack\nfor each (u,v) then do\nif v hasn't been searched then\nTARJAN_SEARCH(v) // 搜索\nlow[u]=min(low[u],low[v]) // 回溯\nelse if v has been in the stack then\nlow[u]=min(low[u],dfn[v])"}, {"k": "p", "x": "对于一个连通分量图，我们很容易想到，在该连通图中有且仅有一个 u 使得 dfn_(u)=low_(u) 。该结点一定是在深度遍历的过程中，该连通分量中第一个被访问过的结点，因为它的 dfn 和 low 值最小，不会被该连通分量中的其他结点所影响。"}, {"k": "p", "x": "因此，在回溯的过程中，判定 dfn_(u)=low_(u) 是否成立，如果成立，则栈中 u 及其上方的结点构成一个 SCC。"}, {"k": "h4", "x": "实现"}, {"k": "code", "x": "int dfn[N], low[N], dfncnt, s[N], in_stack[N], tp;\nint scc[N], sc;  // 结点 i 所在 SCC 的编号\nint sz[N];       // 强连通 i 的大小\n\nvoid tarjan(int u) {\nlow[u] = dfn[u] = ++dfncnt, s[++tp] = u, in_stack[u] = 1;\nfor (int i = h[u]; i; i = e[i].nex) {\nconst int &v = e[i].t;\nif (!dfn[v]) {\ntarjan(v);\nlow[u] = min(low[u], low[v]);\n} else if (in_stack[v]) {\nlow[u] = min(low[u], dfn[v]);\n}\n}\nif (dfn[u] == low[u]) {\n++sc;\ndo {\nscc[s[tp]] = sc;\nsz[sc]++;\nin_stack[s[tp]] = 0;\n} while (s[tp--] != u);\n}\n}"}, {"k": "p", "x": "时间复杂度 O(n + m) 。"}, {"k": "p", "x": "例题："}, {"k": "h4", "x": "Status"}, {"k": "p", "x": "Problem"}, {"k": "h4", "x": "Tags"}, {"k": "p", "x": "P3387"}, {"k": "p", "x": "."}, {"k": "p", "x": "【模板】缩点"}, {"k": "h4", "x": "图论"}, {"k": "p", "x": "P1262"}, {"k": "p", "x": "."}, {"k": "p", "x": "间谍网络"}, {"k": "h4", "x": "图论"}, {"k": "p", "x": "P2002"}, {"k": "p", "x": "."}, {"k": "p", "x": "消息扩散"}, {"k": "h4", "x": "图论"}, {"k": "p", "x": "P2169"}, {"k": "p", "x": "."}, {"k": "p", "x": "正则表达式"}, {"k": "h4", "x": "图论"}, {"k": "p", "x": "P1073"}, {"k": "p", "x": "."}, {"k": "p", "x": "最优贸易"}, {"k": "h4", "x": "图论"}, {"k": "h4", "x": "欧拉路"}, {"k": "h4", "x": "割点与割边"}], "chars": 2619}, {"id": "graph-44", "title": "图论 08 · 割点与割边", "cat": "图论", "blocks": [{"k": "p", "x": "割点"}, {"k": "h4", "x": "定义"}, {"k": "p", "x": "对于一个无向图，如果把一个点删除后这个图的极大连通分量数增加了，那么这个点就是这个图的割点（又称割顶）。"}, {"k": "h4", "x": "过程"}, {"k": "p", "x": "如果我们尝试删除每个点，并且判断这个图的连通性，那么复杂度会特别的高。所以要介绍一个常用的算法：Tarjan。"}, {"k": "p", "x": "对于下图："}, {"k": "p", "x": "很容易的看出割点是 2，而且这个图仅有这一个割点。"}, {"k": "p", "x": "首先，我们按照 DFS 序给他打上时间戳（访问的顺序）。"}, {"k": "p", "x": "这些信息被我们保存在一个叫做 dfn 的数组中。"}, {"k": "p", "x": "还需要另外一个数组 low，用它来存储不经过其父亲能到达的最小的时间戳。"}, {"k": "p", "x": "例如 low[2] 是 1，low[5] 和 low[6] 是 3。"}, {"k": "p", "x": "然后我们开始 DFS，我们判断某个点是否是割点的根据是：对于某个顶点 u ，如果存在至少一个顶点 v （ u 的儿子），使得 low_(v) >= dfn_(u) ，即不能回到祖先，那么 u 点为割点。"}, {"k": "p", "x": "此根据惟独不适用于搜索的起始点，其需要特殊考虑：若该点不是割点，则其他路径亦能到达全部结点，因此从起始点只「向下搜了一次」，即在搜索树内仅有一个子结点。如果在搜索树内有两个及以上的儿子，那么他一定是割点了（设想上图从 2 开始搜索，搜索树内应有两个子结点：3 或 4 及 5 或 6）。如果只有一个儿子，那么把它删掉，不会有任何的影响。比如下面这个图，此处形成了一个环。"}, {"k": "p", "x": "我们在访问 1 的儿子时候，假设先 DFS 到了 2，然后标记用过，然后递归往下，来到了 4，4 又来到了 3，当递归回溯的时候，会发现 3 已经被访问过了，所以不是割点。"}, {"k": "p", "x": "更新 low 的伪代码如下："}, {"k": "p", "x": "1 if v is a son of u 2 low_(u) = min(low_(u), low_(v)) 3 else 4 low_(u) = min(low_(u), dfn_(v))"}, {"k": "h4", "x": "例题"}, {"k": "p", "x": "模板题：【模板】割点（割顶）"}, {"k": "h4", "x": "示例代码"}, {"k": "code", "x": "#include <iostream>\n#include <vector>\nusing namespace std;\nint n, m;  // n：点数 m：边数\nint dfn[100001], low[100001], idx, res;\n// dfn：记录每个点的时间戳\n// low：能不经过父亲到达最小的编号，idx：时间戳，res：答案数量\nbool vis[100001], flag[100001];  // flag: 答案 vis：标记是否重复\nvector<int> edge[100001];        // 存图用的\n\nvoid Tarjan(int u, int fa) {  // u 当前点的编号，fa 自己爸爸的编号\nvis[u] = true;              // 标记\nlow[u] = dfn[u] = ++idx;    // 打上时间戳\nint child = 0;              // 每一个点儿子数量\nfor (const auto &v : edge[u]) {  // 访问这个点的所有邻居（C++11）\nif (!vis[v]) {\nchild++;                       // 多了一个儿子\nTarjan(v, u);                  // 继续\nlow[u] = min(low[u], low[v]);  // 更新能到的最小节点编号\nif (fa != u && low[v] >= dfn[u] && !flag[u]) {  // 主要代码\n// 如果不是自己，且不通过父亲返回的最小点符合割点的要求，并且没有被标记过\n// 要求即为：删了父亲连不上去了，即为最多连到父亲\nflag[u] = true;\nres++;  // 记录答案\n}\n} else if (v != fa) {\n// 如果这个点不是自己的父亲，更新能到的最小节点编号\nlow[u] = min(low[u], dfn[v]);\n}\n}\n// 主要代码，自己的话需要 2 个儿子才可以\nif (fa == u && child >= 2 && !flag[u]) {\nflag[u] = true;\nres++;  // 记录答案\n}\n}\n\nint main() {\ncin >> n >> m;                  // 读入数据\nfor (int i = 1; i <= m; i++) {  // 注意点是从 1 开始的\nint x, y;\ncin >> x >> y;\nedge[x].push_back(y);\nedge[y].push_back(x);\n}  // 使用 vector 存图\nfor (int i = 1; i <= n; i++)  // 因为 Tarjan 图不一定连通\nif (!vis[i]) {\nidx = 0;       // 时间戳初始为 0\nTarjan(i, i);  // 从第 i 个点开始，父亲为自己\n}\ncout << res << endl;\nfor (int i = 1; i <= n; i++)\nif (flag[i]) cout << i << \" \";  // 输出结果\nreturn 0;\n}"}, {"k": "p", "x": "割边（无重边时）"}, {"k": "h4", "x": "定义"}, {"k": "p", "x": "对于一个无向图，如果删掉一条边后图中的连通分量数增加了，则称这条边为桥或者割边。严谨来说，就是：假设有连通图 G=V,E ， e 是其中一条边（即 e 属于 E ），如果 G-e 是不连通的，则边 e 是图 G 的一条割边（桥）。"}, {"k": "p", "x": "比如说，下图中，"}, {"k": "p", "x": "红色的边就是割边。"}, {"k": "h4", "x": "过程"}, {"k": "p", "x": "和割点差不多，只要改一处： low_(v)>dfn_(u) 就可以了，而且不需要考虑根节点的问题。"}, {"k": "p", "x": "割边是和是不是根节点没关系的，原来我们求割点的时候是指点 v 是不可能不经过父节点 u 为回到祖先节点（包括父节点），所以顶点 u 是割点。如果 low_(v)=dfn_(u) 表示还可以回到父节点，如果顶点 v 不能回到祖先也没有另外一条回到父亲的路，那么 u-v 这条边就是割边。"}, {"k": "h4", "x": "实现"}, {"k": "p", "x": "下面代码实现了对 无重边 的无向图求割边，其中，当 isbridge[x] 为真时，(father[x],x) 为一条割边。"}, {"k": "p", "x": "int low[MAXN], dfn[MAXN], idx;\nbool isbridge[MAXN];\nvector<int> G[MAXN];\nint cnt_bridge;\nint father[MAXN];"}, {"k": "code", "x": "void tarjan(int u, int fa) {\nfather[u] = fa;\nlow[u] = dfn[u] = ++idx;\nfor (const auto &v : G[u]) {\nif (!dfn[v]) {\ntarjan(v, u);\nlow[u] = min(low[u], low[v]);\nif (low[v] > dfn[u]) {\nisbridge[v] = true;\n++cnt_bridge;\n}\n} else if (v != fa) {\nlow[u] = min(low[u], dfn[v]);\n}\n}\n}"}, {"k": "p", "x": "割边（有重边时）"}, {"k": "p", "x": "然而，上述无重边时的做法在有重边的无向图上是有问题的。"}, {"k": "p", "x": "因为两节点间可能不止有一条边，此时它们都不会是桥。"}, {"k": "h4", "x": "过程"}, {"k": "p", "x": "一种思路是将参数 fa 改为刚刚走过的边的编号（每条边的编号一致）即可，即将「不用父节点更新」改为「不用来时的边更新」。"}, {"k": "p", "x": "另一种更简单的思路是设立一个标记判断是否已有一条边抵达父节点，标记后再访问到父节点时正常更新。"}, {"k": "p", "x": "下面代码实现了对可能 有重边 的无向图求割边。"}, {"k": "p", "x": "int low[MAXN], dfn[MAXN], idx;\nbool isbridge[MAXN];\nvector<int> G[MAXN];\nint cnt_bridge;\nint father[MAXN];"}, {"k": "code", "x": "void tarjan(int u, int fa) {\nbool flag = false;\nfather[u] = fa;\nlow[u] = dfn[u] = ++idx;\nfor (const auto &v : G[u]) {\nif (!dfn[v]) {\ntarjan(v, u);\nlow[u] = min(low[u], low[v]);\nif (low[v] > dfn[u]) {\nisbridge[v] = true;\n++cnt_bridge;\n}\n} else {\nif (v != fa || flag)\nlow[u] = min(low[u], dfn[v]);\nelse\nflag = true;\n}\n}\n}"}, {"k": "p", "x": "例题："}, {"k": "h4", "x": "Status"}, {"k": "p", "x": "Problem"}, {"k": "h4", "x": "Tags"}, {"k": "p", "x": "B2002"}, {"k": "p", "x": "."}, {"k": "p", "x": "【模板】割点（割顶）"}, {"k": "h4", "x": "图论"}, {"k": "p", "x": "强连通分量与 Tarjan 算法"}, {"k": "h4", "x": "双连通分量"}], "chars": 3613}, {"id": "graph-45", "title": "图论 09 · 双连通分量", "cat": "图论", "blocks": [{"k": "h4", "x": "定义"}, {"k": "p", "x": "在一张连通的无向图中，对于两个点 u 和 v ，如果无论删去哪条边（只能删去一条）都不能使它们不连通，我们就说 u 和 v 边双连通。"}, {"k": "p", "x": "在一张连通的无向图中，对于两个点 u 和 v ，如果无论删去哪个点（只能删去一个，且不能删 u 和 v 自己）都不能使它们不连通，我们就说 u 和 v 点双连通。"}, {"k": "p", "x": "边双连通具有传递性，即，若 x,y 边双连通， y,z 边双连通，则 x,z 边双连通。"}, {"k": "p", "x": "点双连通 不 具有传递性，反例如下图， A,B 点双连通， B,C 点双连通，而 A,C 不 点双连通。"}, {"k": "p", "x": "对于一个无向图中的 极大 边双连通的子图，我们称这个子图为一个 边双连通分量。"}, {"k": "p", "x": "对于一个无向图中的 极大 点双连通的子图，我们称这个子图为一个 点双连通分量。"}, {"k": "h4", "x": "DFS 生成树"}, {"k": "p", "x": "对于一张连通的无向图，我们可以从任意一点开始 DFS，得到原图的一棵 DFS 生成树（以开始 DFS 的那个点为根），这棵生成树上的边称作 树边，不在生成树上的边称作 非树边。"}, {"k": "p", "x": "由于 DFS 的性质，我们可以保证所有非树边连接的两个点在生成树上都满足其中一个是另一个的祖先。"}, {"k": "p", "x": "DFS 的代码如下："}, {"k": "code", "x": "void DFS(int p) {\nvisited[p] = true;\nfor (int to : edge[p])\nif (!visited[to]) DFS(to);\n}"}, {"k": "p", "x": "边双连通分量"}, {"k": "h4", "x": "例题"}, {"k": "p", "x": "对于一个 n 个节点 m 条无向边的图，请输出其边双连通分量的个数，并且输出每个边双连通分量。"}, {"k": "h4", "x": "Tarjan 算法 1"}, {"k": "p", "x": "用 Tarjan 求双连通分量过程与求强连通分量类似，可以先阅读强连通分量的 Tarjan 算法。"}, {"k": "p", "x": "我们考虑先求出所有的桥，再 DFS 求出边双连通分量。"}, {"k": "p", "x": "求桥可参见割点和桥的桥部分。"}, {"k": "p", "x": "时间复杂度 O(n+m) 。"}, {"k": "code", "x": "#include <algorithm>\n#include <iostream>\n#include <vector>"}, {"k": "code", "x": "using namespace std;\nconstexpr int N = 5e5 + 5, M = 2e6 + 5;\nint n, m, ans;\nint tot = 1, hd[N];"}, {"k": "code", "x": "struct edge {\nint to, nt;\n} e[M << 1];"}, {"k": "code", "x": "void add(int u, int v) { e[++tot].to = v, e[tot].nt = hd[u], hd[u] = tot; }"}, {"k": "code", "x": "void uadd(int u, int v) { add(u, v), add(v, u); }"}, {"k": "p", "x": "bool bz[M << 1];\nint bcc_cnt, dfn[N], low[N], vis_bcc[N];\nvector<vector<int>> bcc;"}, {"k": "code", "x": "void tarjan(int x, int in) {\ndfn[x] = low[x] = ++bcc_cnt;\nfor (int i = hd[x]; i; i = e[i].nt) {\nint v = e[i].to;\nif (dfn[v] == 0) {\ntarjan(v, i);\nif (dfn[x] < low[v]) bz[i] = bz[i ^ 1] = true;\nlow[x] = min(low[x], low[v]);\n} else if (i != (in ^ 1))\nlow[x] = min(low[x], dfn[v]);\n}\n}"}, {"k": "code", "x": "void dfs(int x, int id) {\nvis_bcc[x] = id, bcc[id - 1].push_back(x);\nfor (int i = hd[x]; i; i = e[i].nt) {\nint v = e[i].to;\nif (vis_bcc[v] || bz[i]) continue;\ndfs(v, id);\n}\n}"}, {"k": "code", "x": "int main() {\ncin.tie(nullptr)->sync_with_stdio(false);\ncin >> n >> m;\nint u, v;\nfor (int i = 1; i <= m; i++) {\ncin >> u >> v;\nif (u == v) continue;\nuadd(u, v);\n}\nfor (int i = 1; i <= n; i++)\nif (dfn[i] == 0) tarjan(i, 0);\nfor (int i = 1; i <= n; i++)\nif (vis_bcc[i] == 0) {\nbcc.push_back(vector<int>());\ndfs(i, ++ans);\n}\ncout << ans << '\\n';\nfor (int i = 0; i < ans; i++) {\ncout << bcc[i].size();\nfor (int j = 0; j < bcc[i].size(); j++) cout << ' ' << bcc[i][j];\ncout << '\\n';\n}\nreturn 0;\n}"}, {"k": "h4", "x": "Tarjan 算法 2"}, {"k": "p", "x": "我们先总结出一个重要的性质，在无向图中，DFS 生成树上的边不是树边就只有非树边。"}, {"k": "p", "x": "我们联系一下求强连通分量的方法，在无向图中只要一个分量没有桥，那么在 DFS 生成树上，它的所有点都在同一个强连通分量中。"}, {"k": "p", "x": "反过来，在 DFS 生成树上的一个强连通分量，在原无向图中是边双连通分量。"}, {"k": "p", "x": "可以发现，求边双连通分量的过程实际上就是求强连通分量的过程。"}, {"k": "p", "x": "时间复杂度 O(n+m) 。"}, {"k": "code", "x": "#include <algorithm>\n#include <iostream>\n#include <stack>\n#include <vector>"}, {"k": "code", "x": "using namespace std;\nconstexpr int N = 5e5 + 5, M = 2e6 + 5;\nint n, m;"}, {"k": "code", "x": "struct edge {\nint to, nt;\n} e[M << 2];"}, {"k": "h4", "x": "int hd[N << 1], tot = 1;"}, {"k": "code", "x": "void add(int u, int v) { e[++tot] = edge{v, hd[u]}, hd[u] = tot; }"}, {"k": "code", "x": "void uadd(int u, int v) { add(u, v), add(v, u); }"}, {"k": "p", "x": "int bcc_cnt, sum;\nint dfn[N], low[N];\nbool vis[N];\nvector<vector<int>> ans;\nstack<int> st;"}, {"k": "code", "x": "void tarjan(int u, int in) {\nlow[u] = dfn[u] = ++bcc_cnt;\nst.push(u), vis[u] = true;\nfor (int i = hd[u]; i; i = e[i].nt) {\nint v = e[i].to;\nif (i == (in ^ 1)) continue;\nif (!dfn[v])\ntarjan(v, i), low[u] = min(low[u], low[v]);\nelse if (vis[v])\nlow[u] = min(low[u], dfn[v]);\n}\nif (dfn[u] == low[u]) {\nvector<int> t;\nt.push_back(u);\nwhile (st.top() != u)\nt.push_back(st.top()), vis[st.top()] = false, st.pop();\nst.pop(), ans.push_back(t);\n}\n}"}, {"k": "code", "x": "int main() {\ncin.tie(nullptr)->sync_with_stdio(false);\ncin >> n >> m;\nint u, v;\nfor (int i = 1; i <= m; i++) {\ncin >> u >> v;\nif (u != v) uadd(u, v);\n}\nfor (int i = 1; i <= n; i++)\nif (!dfn[i]) tarjan(i, 0);\ncout << ans.size() << '\\n';\nfor (int i = 0; i < ans.size(); i++) {\ncout << ans[i].size() << ' ';\nfor (int j = 0; j < ans[i].size(); j++) cout << ans[i][j] << ' ';\ncout << '\\n';\n}\nreturn 0;\n}"}, {"k": "h4", "x": "差分算法"}, {"k": "p", "x": "和 Tarjan 算法 1 类似，我们先求出所有的桥，再差分求出边双连通分量。"}, {"k": "p", "x": "首先，对原图进行 DFS。"}, {"k": "p", "x": "如上图所示，黑色与绿色边为树边，红色边为非树边。每一条非树边的两个端点都唯一对应了树上的一条由树边构成的简单路径，我们说这条非树边 覆盖 了这条简单路径上所有的边。"}, {"k": "p", "x": "在图中，绿色的树边 至少 被一条非树边覆盖，黑色的树边不被 任何 非树边覆盖。"}, {"k": "p", "x": "显然，非树边 和 绿色的树边 一定不是桥，黑色的树边 一定是桥。"}, {"k": "p", "x": "首先考虑一个暴力的做法，对于每一条非树边，都逐个地将它覆盖的每一条树边置成绿色，时间复杂度为 O(nm) 。"}, {"k": "p", "x": "考虑用差分优化。对于每一条非树边，在其树上深度较小的端点处打上 -1 标记，在其树上深度较大的端点处打上 +1 标记，然后 O(n) 求出每个点的子树内部的标记和。"}, {"k": "p", "x": "对于一个点 u ，其子树内部的标记之和等于覆盖了 u 和 fa_(u) 之间的树边的非树边数量。若这个值等于 0 ，则 u 和 fa_(u) 之间的树边是 桥。"}, {"k": "p", "x": "再用 DFS 求出边双连通分量。"}, {"k": "p", "x": "时间复杂度 O(n+m) 。"}, {"k": "code", "x": "#include <cstring>\n#include <iostream>\n#include <vector>\nusing namespace std;\n#define min(x, y) (x < y ? x : y)\n#define max(x, y) (x > y ? x : y)\nconstexpr int N = 5e5 + 5, M = 2e6 + 5;\nint n, m;\n\nstruct edge {\nint to, nt;\n} e[M << 1];\n\nint hd[N], tot;\n\nvoid add(int u, int v) { e[++tot] = {v, hd[u]}, hd[u] = tot; }\n\nvoid uadd(int u, int v) { add(u, v), add(v, u); }  // 链式前向星\n\nusing ll = long long;\n#define P(x, y) ((ll)min(x, y) * N + (ll)max(x, y))\nconstexpr int hmod = 1e5 + 7;\n\nstruct hash {\nvector<ll> v1[hmod];\nvector<short> v2[hmod];\n\nshort &operator[](ll x) {\nint y = x % hmod;\nfor (int i = 0; i < v1[y].size(); i++)\nif (v1[y][i] == x) return v2[y][i];\nv1[y].push_back(x), v2[y].push_back(0);\nreturn v2[y].back();\n}\n} re, be;  // 用 vector 实现 hash 表，因为本题时空限制均比较紧\n\n// re 判断是否有重边，be 记录边是不是桥\n\n// #define P(x, y) {min(x, y), max(x, y)}\n// using pii = pair<int, int>;\n// map<pii, int> re, be; // 不紧时可以用 map 实现 hash 表\n\nint dep[N], bz[N], sum[N];  // 记录深度、差分值、子树查分和\nint vis[N], fa[N];          // 记录是否访问过，分组编号\n\nvoid dfs(int x, int pre) {  // 计算每个点的深度和单点查分\nif (dep[x] < dep[pre]) bz[x]++, bz[pre]--;  // 回到祖先，更改差分值\nif (dep[x]) return;\ndep[x] = dep[pre] + 1;\nfor (int i = hd[x]; i; i = e[i].nt) dfs(e[i].to, x);\n}\n\nint dfs2(int x, int pre) {  // 处理子树查分\nif (vis[x] == 1) return sum[x];\nvis[x] = 1, sum[x] = bz[x];\nfor (int i = hd[x]; i; i = e[i].nt) {\nint v = e[i].to;\nif (dep[v] > dep[x] && !vis[v]) sum[x] += dfs2(v, x);\n}\nif (sum[x] == 0 && re[P(x, pre)] == 1) be[P(x, pre)] = 1;  // 记录桥\nreturn sum[x];\n}\n\nint cnt;\nvector<int> ans[N];\n\nvoid dfs3(int x) {  // 计算双连通分量\nif (fa[x]) return;\nans[cnt].push_back(x), fa[x] = cnt;\nfor (int i = hd[x]; i; i = e[i].nt) {\nint v = e[i].to;\nif (be[P(x, v)] != 1) dfs3(v);  // 不是桥，递归处理子树\n}\n}\n\nint main() {\ncin.tie(nullptr)->sync_with_stdio(false);\ncin >> n >> m;\nint u, v;\nfor (int i = 1; i <= m; i++) cin >> u >> v, uadd(u, v), re[P(u, v)]++;\nfor (int i = 1; i <= n; i++)\nif (!dep[i]) dfs(i, 0);\nfor (int i = 1; i <= n; i++)\nif (!vis[i]) dfs2(i, 0);\nfor (int i = 1; i <= n; i++)\nif (!fa[i]) cnt++, dfs3(i);\ncout << cnt << '\\n';\nfor (int i = 1; i <= cnt; i++) {\ncout << ans[i].size() << ' ';\nfor (int j = 0; j < ans[i].size(); j++) cout << ans[i][j] << ' ';\ncout << '\\n';\n}\nreturn 0;\n}"}, {"k": "p", "x": "点双连通分量"}, {"k": "h4", "x": "题面"}, {"k": "p", "x": "对于一个 n 个节点 m 条无向边的图，请输出其点双连通分量的个数，并且输出每个点双连通分量。"}, {"k": "h4", "x": "Tarjan 算法"}, {"k": "p", "x": "需要先学习割点，可以先参见割点和桥的割点部分。"}, {"k": "p", "x": "先给出两个性质："}, {"k": "li", "x": "两个点双最多只有一个公共点，且一定是割点。"}, {"k": "li", "x": "对于一个点双，它在 DFS 搜索树中 dfn 值最小的点一定是割点或者树根。"}, {"k": "p", "x": "我们根据第二个性质，分类讨论："}, {"k": "li", "x": "当这个点为割点时，它一定是点双连通分量的根，因为一旦包含它的父节点，他仍然是割点。"}, {"k": "li", "x": "当这个点为树根时："}, {"k": "li", "x": "有两个及以上子树，它是一个割点。"}, {"k": "li", "x": "只有一个子树，它是一个点双连通分量的根。"}, {"k": "li", "x": "它没有子树，视作一个点双。"}, {"k": "code", "x": "#include <iostream>\n#include <vector>\nusing namespace std;\nconstexpr int N = 5e5 + 5, M = 2e6 + 5;\nint n, m;"}, {"k": "code", "x": "struct edge {\nint to, nt;\n} e[M << 1];"}, {"k": "h4", "x": "int hd[N], tot = 1;"}, {"k": "code", "x": "void add(int u, int v) { e[++tot] = edge{v, hd[u]}, hd[u] = tot; }"}, {"k": "code", "x": "void uadd(int u, int v) { add(u, v), add(v, u); }"}, {"k": "p", "x": "int ans;\nint dfn[N], low[N], bcc_cnt;\nint sta[N], top, cnt;\nbool cut[N];\nvector<int> dcc[N];\nint root;"}, {"k": "code", "x": "void tarjan(int u) {\ndfn[u] = low[u] = ++bcc_cnt, sta[++top] = u;\nif (u == root && hd[u] == 0) {\ndcc[++cnt].push_back(u);\nreturn;\n}\nint f = 0;\nfor (int i = hd[u]; i; i = e[i].nt) {\nint v = e[i].to;\nif (!dfn[v]) {\ntarjan(v);\nlow[u] = min(low[u], low[v]);\nif (low[v] >= dfn[u]) {\nif (++f > 1 || u != root) cut[u] = true;\ncnt++;\ndo dcc[cnt].push_back(sta[top--]);\nwhile (sta[top + 1] != v);\ndcc[cnt].push_back(u);\n}\n} else\nlow[u] = min(low[u], dfn[v]);\n}\n}"}, {"k": "code", "x": "int main() {\ncin.tie(nullptr)->sync_with_stdio(false);\ncin >> n >> m;\nint u, v;\nfor (int i = 1; i <= m; i++) {\ncin >> u >> v;\nif (u != v) uadd(u, v);\n}\nfor (int i = 1; i <= n; i++)\nif (!dfn[i]) root = i, tarjan(i);\ncout << cnt << '\\n';\nfor (int i = 1; i <= cnt; i++) {\ncout << dcc[i].size() << ' ';\nfor (int j = 0; j < dcc[i].size(); j++) cout << dcc[i][j] << ' ';\ncout << '\\n';\n}\nreturn 0;\n}"}, {"k": "h4", "x": "差分算法"}, {"k": "p", "x": "如上图所示，黑色边为树边，红色边为非树边，每一条非树边的两个端点都唯一对应了树上由树边构成的的一条简单路径。"}, {"k": "p", "x": "考虑一张新图，新图中的每一个点对应原图中的每一条树边（在图中用蓝色点表示）。对于原图中的每一条非树边，将这条非树边对应的树上简单路径中的所有边在新图中对应的蓝点连成一个连通块（在图中用蓝色的边体现出来）。"}, {"k": "p", "x": "这样，一个点若 不是 割点，当且仅当与其相连的所有边在新图中对应的蓝点都 属于 同一个连通块。"}, {"k": "p", "x": "两个点 是 点双连通，当且仅当它们在原图的树上路径中的所有边在新图中对应的蓝点都 属于 同一个连通块，即图中的每个蓝点构成的连通块都是一个点双连通分量。"}, {"k": "p", "x": "蓝点间的连通关系可以用与求边双连通时用到的差分类似的方法维护，时间复杂度 O(n+m) 。"}, {"k": "p", "x": "例题："}, {"k": "h4", "x": "Status"}, {"k": "p", "x": "Problem"}, {"k": "h4", "x": "Tags"}, {"k": "p", "x": "P8435"}, {"k": "p", "x": "."}, {"k": "p", "x": "【模板】点双连通分量"}, {"k": "h4", "x": "图论"}, {"k": "p", "x": "P3225"}, {"k": "p", "x": "."}, {"k": "p", "x": "矿场搭建"}, {"k": "h4", "x": "图论"}, {"k": "h4", "x": "割点与割边"}, {"k": "h4", "x": "树的直径与重心"}], "chars": 8083}, {"id": "graph-46", "title": "图论 10 · 树的直径与重心", "cat": "图论", "blocks": [{"k": "h4", "x": "树的直径定义"}, {"k": "p", "x": "树上任意两节点之间最长的简单路径即为树的「直径」。"}, {"k": "h4", "x": "引入"}, {"k": "p", "x": "显然，一棵树可以有多条直径，他们的长度相等。"}, {"k": "p", "x": "可以用两次 DFS 或者树形 DP 的方法在 O(n) 时间求出树的直径。"}, {"k": "h4", "x": "例题"}, {"k": "p", "x": "给定一棵 n 个节点的树，求其直径的长度。 1 <= n <= 10^4 。"}, {"k": "p", "x": "做法 1. 两次 DFS"}, {"k": "h4", "x": "过程"}, {"k": "p", "x": "首先从任意节点 y 开始进行第一次 DFS，到达距离其最远的节点，记为 z ，然后再从 z 开始做第二次 DFS，到达距离 z 最远的节点，记为 z' ，则 delta(z,z') 即为树的直径。"}, {"k": "p", "x": "显然，如果第一次 DFS 到达的节点 z 是直径的一端，那么第二次 DFS 到达的节点 z' 一定是直径的一端。我们只需证明在任意情况下， z 必为直径的一端。"}, {"k": "p", "x": "定理：在一棵树上，从任意节点 y 开始进行一次 DFS，到达的距离其最远的节点 z 必为直径的一端。"}, {"k": "h4", "x": "证明"}, {"k": "p", "x": "使用反证法。记出发节点为 y 。设真实的直径是 delta(s,t) ，而从 y 进行的第一次 DFS 到达的距离其最远的节点 z 不为 t 或 s 。共分三种情况："}, {"k": "li", "x": "若 y 在 delta(s,t) 上："}, {"k": "p", "x": "有 delta(y,z) > delta(y,t) Longrightarrow delta(x,z) > delta(x,t) Longrightarrow delta(s,z) > delta(s,t) ，与 delta(s,t) 为树上任意两节点之间最长的简单路径矛盾。"}, {"k": "li", "x": "若 y 不在 delta(s,t) 上，且 delta(y,z) 与 delta(s,t) 存在重合路径："}, {"k": "p", "x": "有 delta(y,z) > delta(y,t) Longrightarrow delta(x,z) > delta(x,t) Longrightarrow delta(s,z) > delta(s,t) ，与 delta(s,t) 为树上任意两节点之间最长的简单路径矛盾。"}, {"k": "li", "x": "若 y 不在 delta(s,t) 上，且 delta(y,z) 与 delta(s,t) 不存在重合路径："}, {"k": "p", "x": "有 delta(y,z) > delta(y,t) Longrightarrow delta(x',z) > delta(x',t) Longrightarrow delta(x,z) > delta(x,t) Longrightarrow delta(s,z) > delta(s,t) ，与 delta(s,t) 为树上任意两节点之间最长的简单路径矛盾。"}, {"k": "p", "x": "综上，三种情况下假设均会产生矛盾，故原定理得证。"}, {"k": "h4", "x": "负权边"}, {"k": "p", "x": "上述证明过程建立在所有路径均不为负的前提下。如果树上存在负权边，则上述证明不成立。故若存在负权边，则无法使用两次 DFS 的方式求解直径。"}, {"k": "h4", "x": "实现"}, {"k": "p", "x": "代码实现如下。"}, {"k": "h4", "x": "constexpr int N = 10000 + 10;"}, {"k": "p", "x": "int n, c, d[N];\nvector<int> E[N];"}, {"k": "code", "x": "void dfs(int u, int fa) {\nfor (int v : E[u]) {\nif (v == fa) continue;\nd[v] = d[u] + 1;\nif (d[v] > d[c]) c = v;\ndfs(v, u);\n}\n}"}, {"k": "code", "x": "int main() {\nscanf(\"%d\", &n);\nfor (int i = 1; i < n; i++) {\nint u, v;\nscanf(\"%d %d\", &u, &v);\nE[u].push_back(v), E[v].push_back(u);\n}\ndfs(1, 0);\nd[c] = 0, dfs(c, 0);\nprintf(\"%d\\n\", d[c]);\nreturn 0;\n}"}, {"k": "p", "x": "如果需要求出一条直径上所有的节点，则可以在第二次 DFS 的过程中，记录每个点的前序节点，即可从直径的一端一路向前，遍历直径上所有的节点。"}, {"k": "p", "x": "做法 2. 树形 DP"}, {"k": "h4", "x": "过程 1"}, {"k": "p", "x": "我们记录当 1 为树的根时，每个节点作为子树的根向下，所能延伸的最长路径长度 d[1] 与次长路径（与最长路径无公共边）长度 d[2] ，那么直径就是对于每一个点，该点 d[1] + d[2] 能取到的值中的最大值。"}, {"k": "p", "x": "树形 DP 可以在存在负权边的情况下求解出树的直径。"}, {"k": "h4", "x": "实现 1"}, {"k": "p", "x": "代码实现如下："}, {"k": "h4", "x": "constexpr int N = 10000 + 10;"}, {"k": "p", "x": "int n, d = 0;\nint d1[N], d2[N];\nvector<int> E[N];"}, {"k": "code", "x": "void dfs(int u, int fa) {\nd1[u] = d2[u] = 0;\nfor (int v : E[u]) {\nif (v == fa) continue;\ndfs(v, u);\nint t = d1[v] + 1;\nif (t > d1[u])\nd2[u] = d1[u], d1[u] = t;\nelse if (t > d2[u])\nd2[u] = t;\n}\nd = max(d, d1[u] + d2[u]);\n}"}, {"k": "code", "x": "int main() {\nscanf(\"%d\", &n);\nfor (int i = 1; i < n; i++) {\nint u, v;\nscanf(\"%d %d\", &u, &v);\nE[u].push_back(v), E[v].push_back(u);\n}\ndfs(1, 0);\nprintf(\"%d\\n\", d);\nreturn 0;\n}"}, {"k": "p", "x": "如果需要求出一条直径上所有的节点，则可以在 DP 的过程中，记录下每个节点能向下延伸的最长路径与次长路径（定义同上）所对应的子节点，在求 d 的同时记下对应的节点 u ，使得 d = d[1][u] + d[2][u] ，即可分别沿着从 u 开始的最长路径的次长路径对应的子节点一路向某个方向（对于无根树，虽然这里指定了 1 为树的根，但仍需记录每点跳转的方向；对于有根树，一路向上跳即可），遍历直径上所有的节点。"}, {"k": "h4", "x": "过程 2"}, {"k": "p", "x": "这里提供一种只使用一个数组进行的树形 DP 方法。"}, {"k": "p", "x": "我们定义 dp[u] ：以 u 为根的子树中，从 u 出发的最长路径。那么容易得出转移方程： dp[u] = max(dp[u], dp[v] + w(u, v)) ，其中的 v 为 u 的子节点， w(u, v) 表示所经过边的权重。"}, {"k": "p", "x": "对于树的直径，实际上是可以通过枚举从某个节点出发不同的两条路径相加的最大值求出。因此，在 DP 求解的过程中，我们只需要在更新 dp[u] 之前，计算 d = max(d, dp[u] + dp[v] + w(u, v)) 即可算出直径 d 。"}, {"k": "h4", "x": "实现 2"}, {"k": "p", "x": "代码实现如下："}, {"k": "h4", "x": "constexpr int N = 10000 + 10;"}, {"k": "p", "x": "int n, d = 0;\nint dp[N];\nvector<int> E[N];"}, {"k": "code", "x": "void dfs(int u, int fa) {\nfor (int v : E[u]) {\nif (v == fa) continue;\ndfs(v, u);\nd = max(d, dp[u] + dp[v] + 1);\ndp[u] = max(dp[u], dp[v] + 1);\n}\n}"}, {"k": "code", "x": "int main() {\nscanf(\"%d\", &n);\nfor (int i = 1; i < n; i++) {\nint u, v;\nscanf(\"%d %d\", &u, &v);\nE[u].push_back(v), E[v].push_back(u);\n}\ndfs(1, 0);\nprintf(\"%d\\n\", d);\nreturn 0;\n}"}, {"k": "h4", "x": "性质"}, {"k": "p", "x": "若树上所有边边权均为正，则树的所有直径中点重合"}, {"k": "p", "x": "证明：使用反证法。设两条中点不重合的直径分别为 delta(s,t) 与 delta(s',t') ，中点分别为 x 与 x' 。显然， delta(s,x) = delta(x,t) = delta(s',x') = delta(x',t') 。"}, {"k": "p", "x": "有 delta(s,t') = delta(s,x) + delta(x,x') + delta(x',t') > delta(s,x) + delta(x,t) = delta(s,t) ，与 delta(s,t) 为树上任意两节点之间最长的简单路径矛盾，故性质得证。"}, {"k": "h4", "x": "树的重心定义"}, {"k": "p", "x": "如果在树中选择某个节点并删除，这棵树将分为若干棵子树，统计子树节点数并记录最大值。取遍树上所有节点，使此最大值取到最小的节点被称为整个树的重心。"}, {"k": "p", "x": "（这里以及下文中的「子树」若无特殊说明都是指无根树的子树，即包括「向上」的那棵子树，并且不包括整棵树自身。）"}, {"k": "h4", "x": "性质"}, {"k": "li", "x": "树的重心如果不唯一，则至多有两个，且这两个重心相邻。"}, {"k": "li", "x": "以树的重心为根时，所有子树的大小都不超过整棵树大小的一半。"}, {"k": "li", "x": "树中所有点到某个点的距离和中，到重心的距离和是最小的；如果有两个重心，那么到它们的距离和一样。"}, {"k": "li", "x": "把两棵树通过一条边相连得到一棵新的树，那么新的树的重心在连接原来两棵树的重心的路径上。"}, {"k": "li", "x": "在一棵树上添加或删除一个叶子，那么它的重心最多只移动一条边的距离。"}, {"k": "h4", "x": "求法"}, {"k": "p", "x": "在 DFS 中计算每个子树的大小，记录「向下」的子树的最大大小，利用总点数 - 当前子树（这里的子树指有根树的子树）的大小得到「向上」的子树的大小，然后就可以依据定义找到重心了。"}, {"k": "code", "x": "// 这份代码默认节点编号从 1 开始，即 i ∈ [1,n]\nint size[MAXN],  // 这个节点的「大小」（所有子树上节点数 + 该节点）\nweight[MAXN],  // 这个节点的「重量」，即所有子树「大小」的最大值\ncentroid[2];  // 用于记录树的重心（存的是节点编号）\n\nvoid GetCentroid(int cur, int fa) {  // cur 表示当前节点 (current)\nsize[cur] = 1;\nweight[cur] = 0;\nfor (int i = head[cur]; i != -1; i = e[i].nxt) {\nif (e[i].to != fa) {  // e[i].to 表示这条有向边所通向的节点。\nGetCentroid(e[i].to, cur);\nsize[cur] += size[e[i].to];\nweight[cur] = max(weight[cur], size[e[i].to]);\n}\n}\nweight[cur] = max(weight[cur], n - size[cur]);\nif (weight[cur] <= n / 2) {  // 依照树的重心的定义统计\ncentroid[centroid[0] != 0] = cur;\n}\n}"}, {"k": "p", "x": "例题："}, {"k": "h4", "x": "Status"}, {"k": "p", "x": "Problem"}, {"k": "h4", "x": "Tags"}, {"k": "p", "x": "P3304"}, {"k": "p", "x": "."}, {"k": "p", "x": "直径"}, {"k": "h4", "x": "图论"}, {"k": "p", "x": "P1395"}, {"k": "p", "x": "."}, {"k": "p", "x": "会议"}, {"k": "h4", "x": "图论"}, {"k": "p", "x": "P2491"}, {"k": "p", "x": "."}, {"k": "p", "x": "[SDOI2011] 消防"}, {"k": "h4", "x": "图论"}, {"k": "h4", "x": "双连通分量"}, {"k": "h4", "x": "最近公共祖先 LCA"}], "chars": 4456}, {"id": "graph-47", "title": "图论 11 · 最近公共祖先 LCA", "cat": "图论", "blocks": [{"k": "h4", "x": "定义"}, {"k": "p", "x": "最近公共祖先简称 LCA（Lowest Common Ancestor）。两个节点的最近公共祖先，就是这两个点的公共祖先里面，离根最远的那个。"}, {"k": "p", "x": "为了方便，我们记某点集 S=v[1],v[2],…,v[n] 的最近公共祖先为 LCA(v[1],v[2],…,v[n]) 或 LCA(S) 。"}, {"k": "h4", "x": "性质"}, {"k": "li", "x": "LCA(u)=u ；"}, {"k": "li", "x": "u 是 v 的祖先，当且仅当 LCA(u,v)=u ；"}, {"k": "li", "x": "如果 u 不为 v 的祖先并且 v 不为 u 的祖先，那么 u,v 分别处于 LCA(u,v) 的两棵不同子树中；"}, {"k": "li", "x": "前序遍历中， LCA(S) 出现在所有 S 中元素之前，后序遍历中 LCA(S) 则出现在所有 S 中元素之后；"}, {"k": "li", "x": "两点集并的最近公共祖先为两点集分别的最近公共祖先的最近公共祖先，即 LCA(A 并 B)=LCA(LCA(A), LCA(B)) ；"}, {"k": "li", "x": "两点的最近公共祖先必定处在树上两点间的最短路上；"}, {"k": "li", "x": "d(u,v)=h(u)+h(v)-2h(LCA(u,v)) ，其中 d 是树上两点间的距离， h 代表某点到树根的距离。"}, {"k": "h4", "x": "求法"}, {"k": "p", "x": "朴素算法"}, {"k": "h4", "x": "过程"}, {"k": "p", "x": "可以每次找深度比较大的那个点，让它向上跳。显然在树上，这两个点最后一定会相遇，相遇的位置就是想要求的 LCA。"}, {"k": "p", "x": "或者先向上调整深度较大的点，令他们深度相同，然后再共同向上跳转，最后也一定会相遇。"}, {"k": "h4", "x": "性质"}, {"k": "p", "x": "朴素算法预处理时需要 dfs 整棵树，时间复杂度为 O(n) ，单次查询时间复杂度为 Theta(n) 。如果树满足随机性质，则时间复杂度与这种随机树的期望高度有关。"}, {"k": "p", "x": "倍增算法"}, {"k": "h4", "x": "过程"}, {"k": "p", "x": "倍增算法是最经典的 LCA 求法，他是朴素算法的改进算法。通过预处理 fa_(x,i) 数组，游标可以快速移动，大幅减少了游标跳转次数。 fa_(x,i) 表示点 x 的第 2^i 个祖先。 fa_(x,i) 数组可以通过 dfs 预处理出来。"}, {"k": "p", "x": "现在我们看看如何优化这些跳转："}, {"k": "p", "x": "在调整游标的第一阶段中，我们要将 u,v 两点跳转到同一深度。我们可以计算出 u,v 两点的深度之差，设其为 y 。通过将 y 进行二进制拆分，我们将 y 次游标跳转优化为「 y 的二进制表示所含 1 的个数」次游标跳转。"}, {"k": "p", "x": "在第二阶段中，我们从最大的 i 开始循环尝试，一直尝试到 0 （包括 0 ），如果 fa_(u,i)not=fa_(v,i) ，则 ugetsfa_(u,i),vgetsfa_(v,i) ，那么最后的 LCA 为 fa_(u,0) 。"}, {"k": "h4", "x": "复杂度"}, {"k": "p", "x": "倍增算法的预处理时间复杂度为 O(n log n) ，单次查询时间复杂度为 O(log n) 。"}, {"k": "p", "x": "另外倍增算法可以通过交换 fa 数组的两维使较小维放在前面。这样可以减少 cache miss 次数，提高程序效率。"}, {"k": "h4", "x": "倍增求 LCA 模板"}, {"k": "code", "x": "#include <cstring>\n#include <iostream>\n#include <vector>\n\nconstexpr int MXN = 40005;\nusing namespace std;\nvector<int> v[MXN];\nvector<int> w[MXN];\n\nint fa[MXN][31], cost[MXN][31], dep[MXN];\nint n, m;\nint a, b, c;\n\n// dfs，用来为 lca 算法做准备。接受两个参数：dfs 起始节点和它的父亲节点。\nvoid dfs(int root, int fno) {\n// 初始化：第 2^0 = 1 个祖先就是它的父亲节点，dep 也比父亲节点多 1。\nfa[root][0] = fno;\ndep[root] = dep[fa[root][0]] + 1;\n// 初始化：其他的祖先节点：第 2^i 的祖先节点是第 2^(i-1) 的祖先节点的第\n// 2^(i-1) 的祖先节点。\nfor (int i = 1; i < 31; ++i) {\nfa[root][i] = fa[fa[root][i - 1]][i - 1];\ncost[root][i] = cost[fa[root][i - 1]][i - 1] + cost[root][i - 1];\n}\n// 遍历子节点来进行 dfs。\nint sz = v[root].size();\nfor (int i = 0; i < sz; ++i) {\nif (v[root][i] == fno) continue;\ncost[v[root][i]][0] = w[root][i];\ndfs(v[root][i], root);\n}\n}\n\n// lca。用倍增算法算取 x 和 y 的 lca 节点。\nint lca(int x, int y) {\n// 令 y 比 x 深。\nif (dep[x] > dep[y]) swap(x, y);\n// 令 y 和 x 在一个深度。\nint tmp = dep[y] - dep[x], ans = 0;\nfor (int j = 0; tmp; ++j, tmp >>= 1)\nif (tmp & 1) ans += cost[y][j], y = fa[y][j];\n// 如果这个时候 y = x，那么 x，y 就都是它们自己的祖先。\nif (y == x) return ans;\n// 不然的话，找到第一个不是它们祖先的两个点。\nfor (int j = 30; j >= 0 && y != x; --j) {\nif (fa[x][j] != fa[y][j]) {\nans += cost[x][j] + cost[y][j];\nx = fa[x][j];\ny = fa[y][j];\n}\n}\n// 返回结果。\nans += cost[x][0] + cost[y][0];\nreturn ans;\n}\n\nvoid Solve() {\ncin.tie(nullptr)->sync_with_stdio(false);\n// 初始化表示祖先的数组 fa，代价 cost 和深度 dep。\nmemset(fa, 0, sizeof(fa));\nmemset(cost, 0, sizeof(cost));\nmemset(dep, 0, sizeof(dep));\n// 读入树：节点数一共有 n 个，查询 m 次，每一次查找两个节点的 lca 点。\ncin >> n >> m;\n// 初始化树边和边权\nfor (int i = 1; i <= n; ++i) {\nv[i].clear();\nw[i].clear();\n}\nfor (int i = 1; i < n; ++i) {\ncin >> a >> b >> c;\nv[a].push_back(b);\nv[b].push_back(a);\nw[a].push_back(c);\nw[b].push_back(c);\n}\n// 为了计算 lca 而使用 dfs。\ndfs(1, 0);\nfor (int i = 0; i < m; ++i) {\ncin >> a >> b;\ncout << lca(a, b) << '\\n';\n}\n}\n\nint main() {\ncin.tie(nullptr)->sync_with_stdio(false);\nint T;\ncin >> T;\nwhile (T--) Solve();\nreturn 0;\n}"}, {"k": "p", "x": "例题："}, {"k": "h4", "x": "Status"}, {"k": "p", "x": "Problem"}, {"k": "h4", "x": "Tags"}, {"k": "p", "x": "P3379"}, {"k": "p", "x": "."}, {"k": "p", "x": "【模板】最近公共祖先（LCA）"}, {"k": "h4", "x": "图论"}, {"k": "p", "x": "P1351"}, {"k": "p", "x": "."}, {"k": "p", "x": "联合权值"}, {"k": "h4", "x": "图论"}, {"k": "p", "x": "P1967"}, {"k": "p", "x": "."}, {"k": "p", "x": "货车运输"}, {"k": "h4", "x": "图论"}, {"k": "p", "x": "P3950"}, {"k": "p", "x": "."}, {"k": "p", "x": "部落冲突"}, {"k": "h4", "x": "图论"}, {"k": "h4", "x": "树的直径与重心"}, {"k": "h4", "x": "树上前缀和与差分"}], "chars": 3140}, {"id": "graph-48", "title": "图论 12 · 树上前缀和与差分", "cat": "图论", "blocks": [{"k": "h4", "x": "树上前缀和定义"}, {"k": "p", "x": "设 sum[i] 表示结点 i 到根节点的权值总和。"}, {"k": "p", "x": "然后："}, {"k": "li", "x": "若是点权， x,y 路径上的和为 sum[x] + sum_(y) - sum_(l)ca - sum_(fa_(l)ca) 。"}, {"k": "li", "x": "若是边权， x,y 路径上的和为 sum[x] + sum_(y) - 2cdotsum_(lca) 。LCA 的求法参见最近公共祖先。"}, {"k": "p", "x": "差分"}, {"k": "h4", "x": "解释"}, {"k": "p", "x": "差分是一种和前缀和相对的策略，可以当做是求和的逆运算。"}, {"k": "p", "x": "这种策略的定义是令 b[i]=a[i]-a[i-1] i 属于 [2,n]"}, {"k": "p", "x": "a[1] i=1"}, {"k": "h4", "x": "性质"}, {"k": "li", "x": "a[i] 的值是 b[i] 的前缀和，即 a[n]= sum limits_(i=1)^nb[i]"}, {"k": "li", "x": "计算 a[i] 的前缀和 sum= sum limits_(i=1)^na[i]= sum limits_(i=1)^n sum limits_(j=1)^ib[j]= sum limits_(i=1)^n(n-i+1)b[i]"}, {"k": "p", "x": "它可以维护多次对序列的一个区间加上一个数，并在最后询问某一位的数或是多次询问某一位的数。注意修改操作一定要在查询操作之前。"}, {"k": "h4", "x": "示例"}, {"k": "p", "x": "譬如使 [l,r] 中的每个数加上一个 k ，即"}, {"k": "h4", "x": "b_(l) <- b_(l) + k,b_(r + 1) <- b_(r + 1) - k"}, {"k": "p", "x": "其中 b_(l)+k=a_(l)+k-a_(l-1) ， b[r+1]-k=a[r+1]-(a[r]+k)"}, {"k": "p", "x": "最后做一遍前缀和就好了。"}, {"k": "h4", "x": "树上差分"}, {"k": "p", "x": "树上差分可以理解为对树上的某一段路径进行差分操作，这里的路径可以类比一维数组的区间进行理解。例如在对树上的一些路径进行频繁操作，并且询问某条边或者某个点在经过操作后的值的时候，就可以运用树上差分思想了。"}, {"k": "p", "x": "树上差分通常会结合最近公共祖先来进行考察。树上差分又分为 点差分 与 边差分，在实现上会稍有不同。"}, {"k": "h4", "x": "点差分"}, {"k": "p", "x": "举例：对树上的一些路径 delta(s[1],t[1]), delta(s[2],t[2]), delta(s[3],t[3])… 进行访问，问一条路径 delta(s,t) 上的点被访问的次数。"}, {"k": "p", "x": "对于一次 delta(s,t) 的访问，需要找到 s 与 t 的公共祖先，然后对这条路径上的点进行访问（点的权值加一），若采用 DFS 算法对每个点进行访问，由于有太多的路径需要访问，时间上承受不了。这里进行差分操作："}, {"k": "p", "x": "d[s] <- d[s]+1 d_(lca) <- d_(lca)-1 d[t] <- d[t]+1 d_(f(lca)) <- d_(f(lca))-1"}, {"k": "p", "x": "其中 f(x) 表示 x 的父亲节点， d[i] 为点权 a[i] 的差分数组。"}, {"k": "p", "x": "可以认为公式中的前两条是对蓝色方框内的路径进行操作，后两条是对红色方框内的路径进行操作。不妨令 lca 左侧的直系子节点为 left 。那么有 d_(lca)-1=a_(lca)-(a_(left)+1) ， d_(f(lca))-1=a_(f(lca))-(a_(lca)+1) 。可以发现实际上点差分的操作和上文一维数组的差分操作是类似的。"}, {"k": "h4", "x": "边差分"}, {"k": "p", "x": "若是对路径中的边进行访问，就需要采用边差分策略了，使用以下公式："}, {"k": "p", "x": "d[s] <- d[s]+1 d[t] <- d[t]+1 d_(lca) <- d_(lca)-2"}, {"k": "p", "x": "由于在边上直接进行差分比较困难，所以将本来应当累加到红色边上的值向下移动到附近的点里，那么操作起来也就方便了。对于公式，有了点差分的理解基础后也不难推导，同样是对两段区间进行差分。"}, {"k": "h4", "x": "例题"}, {"k": "p", "x": "完整题面：Max Flow P"}, {"k": "p", "x": "FJ 给他的牛棚的 N(2 <= N <= 50,000) 个隔间之间安装了 N-1 根管道，隔间编号从 1 到 N 。所有隔间都被管道连通了。"}, {"k": "p", "x": "FJ 有 K(1 <= K <= 100,000) 条运输牛奶的路线，第 i 条路线从隔间 s[i] 运输到隔间 t[i] 。一条运输路线会给它的两个端点处的隔间以及中间途径的所有隔间带来一个单位的运输压力，你需要计算压力最大的隔间的压力是多少。"}, {"k": "h4", "x": "解题思路"}, {"k": "p", "x": "需要统计每个点经过了多少次，那么就用树上差分将每一次的路径上的点加一，可以很快得到每个点经过的次数。这里采用倍增法计算 LCA，最后对 DFS 遍历整棵树，在回溯时对差分数组求和就能求得答案了。"}, {"k": "h4", "x": "参考代码"}, {"k": "code", "x": "#include <algorithm>\n#include <iostream>\nusing namespace std;\n\nconstexpr int MAXN = 50010;\n\nstruct node {\nint to, next;\n} edge[MAXN << 1];\n\nint fa[MAXN][30], head[MAXN << 1];\nint power[MAXN];\nint depth[MAXN], lg[MAXN];\nint n, k, ans = 0, tot = 0;\n\nvoid add(int x, int y) {  // 加边\nedge[++tot].to = y;\nedge[tot].next = head[x];\nhead[x] = tot;\n}\n\nvoid dfs(int now, int father) {  // dfs 求最大压力\nfa[now][0] = father;\ndepth[now] = depth[father] + 1;\nfor (int i = 1; i <= lg[depth[now]]; ++i)\nfa[now][i] = fa[fa[now][i - 1]][i - 1];\nfor (int i = head[now]; i; i = edge[i].next)\nif (edge[i].to != father) dfs(edge[i].to, now);\n}\n\nint lca(int x, int y) {  // 求 LCA，最近公共祖先\nif (depth[x] < depth[y]) swap(x, y);\nwhile (depth[x] > depth[y]) x = fa[x][lg[depth[x] - depth[y]] - 1];\nif (x == y) return x;\nfor (int k = lg[depth[x]] - 1; k >= 0; k--) {\nif (fa[x][k] != fa[y][k]) x = fa[x][k], y = fa[y][k];\n}\nreturn fa[x][0];\n}\n\n// 用 dfs 求最大压力，回溯时将子树的权值加上\nvoid get_ans(int u, int father) {\nfor (int i = head[u]; i; i = edge[i].next) {\nint to = edge[i].to;\nif (to == father) continue;\nget_ans(to, u);\npower[u] += power[to];\n}\nans = max(ans, power[u]);\n}\n\nint main() {\ncin.tie(nullptr)->sync_with_stdio(false);\ncin >> n >> k;\nint x, y;\nfor (int i = 1; i <= n; i++) {\nlg[i] = lg[i - 1] + (1 << lg[i - 1] == i);\n}\nfor (int i = 1; i <= n - 1; i++) {  // 建图\ncin >> x >> y;\nadd(x, y);\nadd(y, x);\n}\ndfs(1, 0);\nint s, t;\nfor (int i = 1; i <= k; i++) {\ncin >> s >> t;\nint ancestor = lca(s, t);\n// 树上差分\npower[s]++;\npower[t]++;\npower[ancestor]--;\npower[fa[ancestor][0]]--;\n}\nget_ans(1, 0);\ncout << ans << '\\n';\nreturn 0;\n}"}, {"k": "p", "x": "例题："}, {"k": "h4", "x": "Status"}, {"k": "p", "x": "Problem"}, {"k": "h4", "x": "Tags"}, {"k": "p", "x": "P8805"}, {"k": "p", "x": "."}, {"k": "p", "x": "机房"}, {"k": "h4", "x": "图论"}, {"k": "p", "x": "P8201"}, {"k": "p", "x": "."}, {"k": "p", "x": "生活在树上"}, {"k": "h4", "x": "图论"}, {"k": "p", "x": "最近公共祖先 LCA"}, {"k": "h4", "x": "最长路"}], "chars": 3399}, {"id": "graph-49", "title": "图论 13 · 最长路", "cat": "图论", "blocks": [{"k": "h4", "x": "最长路"}, {"k": "p", "x": "最长路是与最短路相对应的概念，最短路是指路径长度最短的路径，最长路则是路径长度最长的路径。"}, {"k": "p", "x": "最长路的求解方法主要有两种：SPFA 算法和拓扑排序算法。拓扑排序算法的执行效率通常显著高于 SPFA 算法。需要说明的是，尽管 SPFA 算法存在容易被特殊数据构造卡时间的情况，但该算法在处理负边权问题上具有独特价值，建议学习者掌握该算法。"}, {"k": "h4", "x": "SPFA 算法"}, {"k": "p", "x": "SPFA 算法能够处理包含负边权的图结构。由于负数的特性，数值越小其绝对值越大，因此可以将最长路问题转化为最短路问题求解。具体方法为：在存储边权时取其相反数，通过最短路算法求解后，再将结果取相反数即可得到最长路的数值。"}, {"k": "h4", "x": "拓扑排序算法"}, {"k": "p", "x": "拓扑排序算法的应用存在一定限制，仅适用于有向无环图，无法直接处理无向图等结构。该算法需要结合动态规划（DP）思想实现，具体思路可通过代码实现进行理解。以下通过例题进行讲解："}, {"k": "p", "x": "题面：最长路"}, {"k": "h4", "x": "SPFA 求最长路示例代码"}, {"k": "code", "x": "#include <bits/stdc++.h>\nusing namespace std;\nint n,m,u,v,w,tot;\nint dis[510010],vis[510010],head[510010];\n\nstruct node {\nint to,net,val;\n} e[510010];\n\ninline void add(int u,int v,int w) {\ne[++tot].to=v;\ne[tot].net=head[u];\ne[tot].val=w;\nhead[u]=tot;\n}\n//链式前向星建边\ninline void spfa() {\nqueue<int> q;\nfor(register int i=1;i<=n;i++) dis[i]=20050206;\ndis[1]=0;\nvis[1]=1;\nq.push(1);\nwhile(!q.empty()) {\nint x=q.front();\nq.pop();\nvis[x]=0;\nfor(register int i=head[x];i;i=e[i].net) {\nint v=e[i].to;\nif(dis[v]>dis[x]+e[i].val) {\ndis[v]=dis[x]+e[i].val;\nif(!vis[v]) {\nvis[v]=1;\nq.push(v);\n}\n}\n}\n}\n}//正常跑最短路\n\nint main() {\nscanf(\"%d%d\",&n,&m);\nfor(register int i=1;i<=m;i++) {\nscanf(\"%d%d%d\",&u,&v,&w);\nadd(u,v,-w);//存一个相反数\n}\nspfa();\nif(dis[n]==20050206) puts(\"-1\"); //到不了就 -1\nelse printf(\"%d\",-dis[n]);//记得存回来\nreturn 0;\n}"}, {"k": "h4", "x": "拓扑排序求最长路示例代码"}, {"k": "code", "x": "#include<bits/stdc++.h>\nusing namespace std;\nconst int MAXN=2*5*1e4;\nint n,m;\nstruct edge{\nint net,to,w;\n}e[MAXN];\nint head[MAXN],tot;\nvoid add(int x,int y,int z){\ne[++tot].net=head[x];\ne[tot].to=y;\ne[tot].w=z;\nhead[x]=tot;\n}\n//链式前向星建边\nbool v[MAXN];\n//用来标记是否可以从 1 走到这个点\n//因为是 1 到 n，所以如果不能从 1 开始走\n//说明不满足条件，没有这条最长路\nint ru[MAXN];\nint ans[MAXN];\nqueue<int>q;\nvoid toop(){\nfor(register int i=1;i<=n;i++){\nif(ru[i]==0) q.push(i);\n}//入度为 0 的进队\nwhile(!q.empty()){\nint x=q.front();\nq.pop();//出队\nfor(register int i=head[x];i;i=e[i].net){\nint y=e[i].to,z=e[i].w;\nru[y]--;//入度--\nif(v[x]==true){\nans[y]=max(ans[y],ans[x]+z);\nv[y]=true;\n}//如果这个节点能从 1 走到，说明它的边可以走\n//更新最长路\nif(ru[y]==0) q.push(y);//进队\n}\n}\n}\nint main(){\nscanf(\"%d%d\",&n,&m);\nfor(register int i=1;i<=m;i++){\nint u,v,w;\nscanf(\"%d%d%d\",&u,&v,&w);\nadd(u,v,w);\nru[v]++;\n}//建边，入度++\nv[1]=true;//1 肯定自己能走\nans[n]=-1;//初始值为 -1，方便输出\ntoop();//拓扑排序求最长路\ncout<<ans[n];\nreturn 0;\n}"}, {"k": "p", "x": "例题："}, {"k": "h4", "x": "Status"}, {"k": "p", "x": "Problem"}, {"k": "h4", "x": "Tags"}, {"k": "p", "x": "P1807"}, {"k": "p", "x": "."}, {"k": "p", "x": "最长路"}, {"k": "h4", "x": "图论"}, {"k": "p", "x": "树上前缀和与差分"}, {"k": "h4", "x": "单源次短路径"}], "chars": 2178}, {"id": "graph-50", "title": "图论 14 · 单源次短路径", "cat": "图论", "blocks": [{"k": "h4", "x": "非严格次短路"}, {"k": "p", "x": "在理解最短路和最长路的概念后，次短路的概念可定义为：除最短路之外的最短路径（允许与最短路长度相等）。"}, {"k": "p", "x": "本文仅介绍一种常用方法，A*算法可用于求解 K 短路问题，因复杂度较高暂不展开。次短路的求解依赖于最短路的结果，需首先计算出最短路。"}, {"k": "p", "x": "次短路的长度必然大于或等于最短路长度。通过分析可知，次短路至少存在一条边不属于最短路径（可能与最短路径无交集）。基于此特性，求解次短路的思路为：记录最短路径中的边，依次删除最短路径中的每条边后重新计算最短路，通过比较所有结果得到次短路。以下通过例题具体说明："}, {"k": "p", "x": "例题：集合位置"}, {"k": "p", "x": "该问题为次短路的典型模板题。解题步骤如下："}, {"k": "p", "x": "1、首先构建图结构（注意使用双精度浮点型存储边权及结果，并进行精度处理）"}, {"k": "p", "x": "2、然后执行“计算最短路 -> 记录路径 -> 枚举删除路径边并重新计算最短路 -> 处理结果”的流程。"}, {"k": "p", "x": "需注意特殊情况处理：若存在多条最短路径，删除部分边后仍可能得到最短路；若起点与终点间仅有一条简单路径（即最短路），删除边后可能导致无法到达终点，此时次短路无解。"}, {"k": "code", "x": "#include<bits/stdc++.h>\nusing namespace std;\nconst int MAXN=1e7+50;\nconst double INF=200500305;\nint n,m;\nint x[MAXN],y[MAXN];\nstruct node{\nint net,to,from;\ndouble w;\n}e[MAXN];\nint head[MAXN],tot;\nvoid add(int u,int v,double w){\ne[++tot].net=head[u];\ne[tot].to=v;\ne[tot].from=u;\n//这里的 from 和 to 表示这一条边的两个端点\n//在后面的程序中用来比较求次短路\ne[tot].w=w;\nhead[u]=tot;\n}\n//链式前向星建边\ndouble d[MAXN];\nint bian[MAXN]; //记录最短路\nbool v[MAXN];\ninline bool ok(int i,int j){\nif(min(e[i].to,e[i].from)==min(e[j].to,e[j].from)&&max(e[i].to,e[i].from)==max(e[j].to,e[j].from))return 0;\nreturn 1;\n}//这一坨长长的东西用来判断是不是我这次要删掉的边\nvoid dij(int s,int p){ //p 用来表示删除哪一条边\npriority_queue<pair<double,int> >q;\nfor(register int i=1;i<=n;i++) d[i]=INF,v[i]=false;\nd[s]=0; //初始化\nq.push(make_pair(0,s));\nwhile(!q.empty()){\nint x=q.top().second;\nq.pop();\nif(v[x]==true) continue;\nv[x]=true;\nfor(register int i=head[x];i;i=e[i].net)\nif(p==-1||ok(i,p)){  //如果是第一次跑最短路就记录路径，如果是该边被删去就不跑\nint y=e[i].to;\ndouble z=e[i].w;\nif(d[y]>d[x]+z){\nd[y]=d[x]+z;\nif(p==-1)bian[y]=i; //第一次跑最短路记录路径\nq.push(make_pair(-d[y],y));\n}\n}\n}\n}\ndouble Min(double x,double y){\nif(x<=y) return x;\nreturn y;\n} //c++ 自带的 min 不支持 double 类型的比较\nint main(){\nscanf(\"%d%d\",&n,&m);\nfor(register int i=1;i<=n;i++) scanf(\"%d%d\",&x[i],&y[i]);\nfor(register int i=1;i<=m;i++){\nint u,v;\ndouble w;\nscanf(\"%d%d\",&u,&v);\nw=(double)sqrt((x[u]-x[v])*(x[u]-x[v])+(y[u]-y[v])*(y[u]-y[v]));\nadd(u,v,w);\nadd(v,u,w);\n}//建双向变\ndij(1,-1); //第一次跑最短路不删边\nint t=n; //用 t 来代替 n，遍历最短路的边\ndouble ans=INF;\nwhile(t!=1){\nint i=bian[t];\ndij(1,i);\nans=min(ans,d[n]); //取一个更小的答案表示次短路\nt=e[bian[t]].from; //遍历最短路的路径\n}\nprintf(\"%.2lf\",ans); //输出答案\nreturn 0;\n}"}, {"k": "h4", "x": "严格次短路"}, {"k": "p", "x": "使用非严格次短路的算法求解此题时会出现错误，因该问题要求严格次短路（长度必须严格大于最短路）。"}, {"k": "p", "x": "严格次短路的求解需确保结果严格大于最短路长度。"}, {"k": "p", "x": "具体方法为：预处理双向最短路，使用 d1 数组存储起点到各点的最短路长度，d2 数组存储各点到终点的最短路长度。通过枚举所有边，结合双向最短路数据计算严格次短路。"}, {"k": "code", "x": "#include<bits/stdc++.h>\n#define M 1000051\n#define N 5005\nusing namespace std;\nint n,m;\nstruct node{\nint net,to,z;\n}e[M];\nint head[N],tot;\nqueue<int>q;\nint d1[N],d2[N]; //同上\nbool v[N];\nvoid add(int x,int y,int z){\ne[++tot].net=head[x];\ne[tot].to=y;\ne[tot].z=z;\nhead[x]=tot;\n}\nvoid spfas(int s){\nfor(register int i=1;i<=n;i++){\nd1[i]=20040915,v[i]=false;\n}\nd1[s]=0;\nv[s]=true;\nq.push(s);\nwhile(!q.empty()){\nint x=q.front();\nq.pop();\nv[x]=false;\nfor(register int i=head[x];i;i=e[i].net){\nint y=e[i].to,z=e[i].z;\nif(d1[y]>d1[x]+z){\nd1[y]=d1[x]+z;\nif(v[y]==false){\nv[y]=true;\nq.push(y);\n}\n}\n}\n}\n}\nvoid spfae(int s){\nfor(register int i=1;i<=n;i++){\nd2[i]=20040915,v[i]=false;\n}\nd2[s]=0;\nv[s]=true;\nq.push(s);\nwhile(!q.empty()){\nint x=q.front();\nq.pop();\nv[x]=false;\nfor(register int i=head[x];i;i=e[i].net){\nint y=e[i].to,z=e[i].z;\nif(d2[y]>d2[x]+z){\nd2[y]=d2[x]+z;\nif(v[y]==false){\nv[y]=true;\nq.push(y);\n}\n}\n}\n}\n}\nint main(){\nscanf(\"%d%d\",&n,&m);\nfor(register int i=1;i<=m;i++){\nint x,y,z;\nscanf(\"%d%d%d\",&x,&y,&z);\nadd(x,y,z);\nadd(y,x,z);\n}\nspfas(1); //预处理 d1\nspfae(n); //预处理 d2\nint minn=d1[n],now=20040915;\n//记录最短路，并将次短路改为极大值\nfor(register int i=1;i<=n;i++){\nfor(register int j=head[i];j;j=e[j].net){ //枚举每一个点的出边\nif(d1[i]+d2[e[j].to]+e[j].z>minn) now=min(now,d1[i]+d2[e[j].to]+e[j].z);\n//如果比最短路大，那么更新次短路\n}\n}\ncout<<now;\nreturn 0;\n}"}, {"k": "p", "x": "例题："}, {"k": "h4", "x": "Status"}, {"k": "p", "x": "Problem"}, {"k": "h4", "x": "Tags"}, {"k": "p", "x": "P2176"}, {"k": "p", "x": "."}, {"k": "p", "x": "RoadBlock S"}, {"k": "h4", "x": "图论"}, {"k": "h4", "x": "最长路"}, {"k": "h4", "x": "Prufer 序列与 Caley 公式"}], "chars": 3619}, {"id": "graph-51", "title": "图论 15 · Prufer 序列与 Caley 公式", "cat": "图论", "blocks": [{"k": "p", "x": "本文介绍 Prüfer 序列 (Prüfer code)，这是一种将带标号的树用一个唯一的整数序列表示的方法。"}, {"k": "p", "x": "使用 Prüfer 序列可以证明凯莱 Caley 公式。并且我们也会讲解如何计算在一个图中加边使图连通的方案数。"}, {"k": "p", "x": "注意：我们不考虑含有 1 个结点的树。"}, {"k": "p", "x": "Prüfer 序列"}, {"k": "h4", "x": "引入"}, {"k": "p", "x": "Prüfer 序列可以将一个带标号 n 个结点的树用 [1,n] 中的 n-2 个整数表示。你也可以把它理解为完全图的生成树与数列之间的双射。常用组合计数问题中。"}, {"k": "h4", "x": "对树建立 Prüfer 序列"}, {"k": "p", "x": "Prüfer 是这样建立的：每次选择一个编号最小的叶结点并删掉它，然后在序列中记录下它连接到的那个结点。重复 n-2 次后就只剩下两个结点，算法结束。"}, {"k": "h4", "x": "显然使用堆可以做到 O(nlog n) 的复杂度"}, {"k": "code", "x": "//注意本代码节点从0开始标号\nvector<vector<int>> adj;\n\nvector<int> pruefer_code() {\nint n = adj.size();\nset<int> leafs;\nvector<int> degree(n);\nvector<bool> killed(n);\nfor (int i = 0; i < n; i++) {\ndegree[i] = adj[i].size();\nif (degree[i] == 1) leafs.insert(i);\n}\n\nvector<int> code(n - 2);\nfor (int i = 0; i < n - 2; i++) {\nint leaf = *leafs.begin();\nleafs.erase(leafs.begin());\nkilled[leaf] = true;\nint v;\nfor (int u : adj[leaf])\nif (!killed[u]) v = u;\ncode[i] = v;\nif (--degree[v] == 1) leafs.insert(v);\n}\nreturn code;\n}"}, {"k": "p", "x": "例如，这是一棵 7 个结点的树的 Prüfer 序列构建过程："}, {"k": "p", "x": "最终的序列就是 2,2,3,3,2 。"}, {"k": "p", "x": "当然，也有一个线性的构造算法。"}, {"k": "h4", "x": "Prüfer 序列的线性构造算法"}, {"k": "p", "x": "线性构造的本质就是维护一个指针指向我们将要删除的结点。首先发现，叶结点数是非严格单调递减的，删去一个叶结点，叶结点总数要么不变要么减 1。"}, {"k": "p", "x": "于是我们考虑这样一个过程：维护一个指针 p 。初始时 p 指向编号最小的叶结点。同时我们维护每个结点的度数，方便我们知道在删除结点的时侯是否产生新的叶结点。操作如下："}, {"k": "li", "x": "删除 p 指向的结点，并检查是否产生新的叶结点。"}, {"k": "li", "x": "如果产生新的叶结点，假设编号为 x ，我们比较 p,x 的大小关系。如果 x>p ，那么不做其他操作；否则就立刻删除 x ，然后检查删除 x 后是否产生新的叶结点，重复 2 步骤，直到未产生新节点或者新节点的编号 >p 。"}, {"k": "li", "x": "让指针 p 自增直到遇到一个未被删除叶结点为止；"}, {"k": "h4", "x": "正确性"}, {"k": "p", "x": "循环上述操作 n-2 次，就完成了序列的构造。接下来考虑算法的正确性。"}, {"k": "p", "x": "p 是当前编号最小的叶结点，若删除 p 后未产生叶结点，我们就只能去寻找下一个叶结点；若产生了叶结点 x ："}, {"k": "li", "x": "如果 x>p ，则反正 p 往后扫描都会扫到它，于是不做操作；"}, {"k": "li", "x": "如果 x<p ，因为 p 原本就是编号最小的，而 x 比 p 还小，所以 x 就是当前编号最小的叶结点，优先删除。删除 x 继续这样的考虑直到没有更小的叶结点。"}, {"k": "p", "x": "算法复杂度分析，发现每条边最多被访问一次（在删度数的时侯），而指针最多遍历每个结点一次，因此复杂度是 O(n) 的。"}, {"k": "h4", "x": "实现"}, {"k": "code", "x": "//同样以 0 为起点\nvector<vector<int>> adj;\nvector<int> parent;\n\nvoid dfs(int v) {\nfor (int u : adj[v]) {\nif (u != parent[v]) parent[u] = v, dfs(u);\n}\n}\n\nvector<int> pruefer_code() {\nint n = adj.size();\nparent.resize(n), parent[n - 1] = -1;\ndfs(n - 1);\n\nint ptr = -1;\nvector<int> degree(n);\nfor (int i = 0; i < n; i++) {\ndegree[i] = adj[i].size();\nif (degree[i] == 1 && ptr == -1) ptr = i;\n}\n\nvector<int> code(n - 2);\nint leaf = ptr;\nfor (int i = 0; i < n - 2; i++) {\nint next = parent[leaf];\ncode[i] = next;\nif (--degree[next] == 1 && next < ptr) {\nleaf = next;\n} else {\nptr++;\nwhile (degree[ptr] != 1) ptr++;\nleaf = ptr;\n}\n}\nreturn code;\n}"}, {"k": "h4", "x": "Prüfer 序列的性质"}, {"k": "li", "x": "在构造完 Prüfer 序列后原树中会剩下两个结点，其中一个一定是编号最大的点 n 。"}, {"k": "li", "x": "每个结点在序列中出现的次数是其度数减 1 。（没有出现的就是叶结点）"}, {"k": "h4", "x": "用 Prüfer 序列重建树"}, {"k": "p", "x": "重建树的方法是类似的。根据 Prüfer 序列的性质，我们可以得到原树上每个点的度数。然后你也可以得到编号最小的叶结点，而这个结点一定与 Prüfer 序列的第一个数连接。然后我们同时删掉这两个结点的度数。"}, {"k": "p", "x": "讲到这里也许你已经知道该怎么做了。每次我们选择一个度数为 1 的最小的结点编号，与当前枚举到的 Prüfer 序列的点连接，然后同时减掉两个点的度。到最后我们剩下两个度数为 1 的点，其中一个是结点 n 。就把它们建立连接。使用堆维护这个过程，在减度数的过程中如果发现度数减到 1 就把这个结点添加到堆中，这样做的复杂度是 O(nlog n) 的。"}, {"k": "code", "x": "vector<pair<int, int>> pruefer_decode(vector<int> const& code) {\nint n = code.size() + 2;\nvector<int> degree(n, 1);\nfor (int i : code) degree[i]++;"}, {"k": "code", "x": "set<int> leaves;\nfor (int i = 0; i < n; i++)\nif (degree[i] == 1) leaves.insert(i);"}, {"k": "code", "x": "vector<pair<int, int>> edges;\nfor (int v : code) {\nint leaf = *leaves.begin();\nleaves.erase(leaves.begin());"}, {"k": "code", "x": "edges.emplace_back(leaf, v);\nif (--degree[v] == 1) leaves.insert(v);\n}\nedges.emplace_back(*leaves.begin(), n - 1);\nreturn edges;\n}"}, {"k": "h4", "x": "线性时间重建树"}, {"k": "p", "x": "同线性构造 Prüfer 序列的方法。在删度数的时侯会产生新的叶结点，于是判断这个叶结点与指针 p 的大小关系，如果更小就优先考虑它。"}, {"k": "h4", "x": "实现"}, {"k": "code", "x": "vector<pair<int, int>> pruefer_decode(vector<int> const& code) {\nint n = code.size() + 2;\nvector<int> degree(n, 1);\nfor (int i : code) degree[i++];"}, {"k": "code", "x": "int ptr = 0;\nwhile (degree[ptr] != 1) ptr++;\nint leaf = ptr;"}, {"k": "code", "x": "vector<pair<int, int>> edges;\nfor (int v : code) {\nedges.emplace_back(leaf, v);\nif (--degree[v] == 1 && v < ptr) {\nleaf = v;\n} else {\nptr++;\nwhile (degree[ptr] != 1) ptr++;\nleaf = ptr;\n}\n}\nedges.emplace_back(leaf, n - 1);\nreturn edges;\n}"}, {"k": "p", "x": "通过这些过程其实可以理解，Prüfer 序列与带标号无根树建立了双射关系。"}, {"k": "p", "x": "Cayley 公式 (Cayley's formula)"}, {"k": "p", "x": "完全图 K[n] 有 n^(n-2) 棵生成树。"}, {"k": "p", "x": "怎么证明？方法很多，但是用 Prüfer 序列证是很简单的。任意一个长度为 n-2 的值域 [1,n] 的整数序列都可以通过 Prüfer 序列双射对应一个生成树，于是方案数就是 n^(n-2) 。"}, {"k": "h4", "x": "图连通方案数"}, {"k": "p", "x": "Prüfer 序列可能比你想得还强大。它能创造比凯莱公式更通用的公式。比如以下问题："}, {"k": "p", "x": "一个 n 个点 m 条边的带标号无向图有 k 个连通块。我们希望添加 k-1 条边使得整个图连通。求方案数。"}, {"k": "h4", "x": "证明"}, {"k": "p", "x": "设 s[i] 表示每个连通块的数量。我们对 k 个连通块构造 Prüfer 序列，然后你发现这并不是普通的 Prüfer 序列。因为每个连通块的连接方法很多。不能直接淦就设啊。于是设 d[i] 为第 i 个连通块的度数。由于度数之和是边数的两倍，于是 sum _(i=1)^(k)d[i]=2k-2 。则对于给定的 d 序列构造 Prüfer 序列的方案数是"}, {"k": "p", "x": "C(k-2,d[1]-1,d[2]-1,...,d[k]-1)=((k-2)!)/((d[1]-1)!(d[2]-1)!...(d[k]-1)!)"}, {"k": "p", "x": "对于第 i 个连通块，它的连接方式有 s[i]^(d[i]) 种，因此对于给定 d 序列使图连通的方案数是"}, {"k": "p", "x": "C(k-2,d[1]-1,d[2]-1,...,d[k]-1)· prod _(i=1)^(k)s[i]^(d[i])"}, {"k": "p", "x": "现在我们要枚举 d 序列，式子变成"}, {"k": "p", "x": "sum d[i] >= 1， sum (i=1)^(k)d[i]=2k-2C(k-2,d[1]-1,d[2]-1,...,d[k]-1)· prod _(i=1)^(k)s[i]^(d[i])"}, {"k": "p", "x": "好的这是一个非常不喜闻乐见的式子。但是别慌！我们有多元二项式定理："}, {"k": "p", "x": "(x[1] + … + x_(m))^(p) = sum substackc[i] >= 0 , sum (i=1)^(m) c[i] = p C(p,c[1], c[2], ... ,c_(m))· prod _(i=1)^(m)x[i]^(c[i])"}, {"k": "p", "x": "那么我们对原式做一下换元，设 e[i]=d[i]-1 ，显然 sum _(i=1)^(k)e[i]=k-2 ，于是原式变成"}, {"k": "p", "x": "sum e[i] >= 0， sum (i=1)^(k)e[i]=k-2C(k-2,e[1],e[2],...,e[k])· prod _(i=1)^(k)s[i]^(e[i]+1)"}, {"k": "h4", "x": "化简得到"}, {"k": "p", "x": "(s[1]+s[2]+...+s[k])^(k-2)· prod _(i=1)^(k)s[i]"}, {"k": "h4", "x": "答案即"}, {"k": "p", "x": "n^(k-2)· prod _(i=1)^(k)s[i]"}, {"k": "p", "x": "例题："}, {"k": "h4", "x": "Status"}, {"k": "p", "x": "Problem"}, {"k": "h4", "x": "Tags"}, {"k": "p", "x": "P6086"}, {"k": "p", "x": "."}, {"k": "p", "x": "【模板】Prufer 序列"}, {"k": "h4", "x": "图论"}, {"k": "p", "x": "P9619"}, {"k": "p", "x": "."}, {"k": "p", "x": "生成树"}, {"k": "h4", "x": "图论"}, {"k": "p", "x": "P4981"}, {"k": "p", "x": "."}, {"k": "p", "x": "父子"}, {"k": "h4", "x": "图论"}, {"k": "h4", "x": "单源次短路径"}, {"k": "h4", "x": "字符串基础知识及常用术语"}], "chars": 4742}];
